let SANTORAL = [];

function saintImageHtml(s, detail=false){
  const src = s.image;
  if(!src) return '';
  return detail
    ? `<div class="saint-image-detail fade-in"><img src="${src}" alt="Imagem de ${escapeHtml(s.title)}"><div class="saint-image-caption">Imagem original com aprimoramento de nitidez.</div></div>`
    : `<div class="saint-thumb"><img src="${src}" alt="Imagem de ${escapeHtml(s.title)}"></div>`;
}

const PRAYERS = {"regra": {"intro": "Regra de Vida\nda Ordem Secular dos Servos de\nMaria\nOSSM\nAos irmãos e irmãs da Ordem Secular dos\nServos de Maria\nProt. 415/95\nO mesmo Espírito Santo que em 1233 chamou\nos nossos Primeiros Pais, hoje convoca todos vocês,\nirmãos e irmãs, para que deem testemunho do\nEvangelho em comunhão fraterna e se coloquem a\nserviço de Deus e do próximo, inspirando-se\nconstantemente em Maria, Mãe e Serva do Senhor.\nCristo Ressuscitado convida-os a percorrer o\nmesmo caminho de santidade que há 762 anos vem\nsendo trilhado pelos irmãos e irmãs da nossa Ordem, e\na prolongar em suas famílias e comunidades cristãs a\npresença operante de Maria, Mãe de Jesus.\nA Sé Apostólica, ao aprovar em 29 de abril de\n1995 a presente “Regra de Vida”, mostra ter em grande\napreço o caminho que vocês e suas fraternidades\npercorreram, guiados pelas diretrizes do Concílio\nVaticano II e da Regra aprovada experimentalmente\nem 2 de outubro de 1982 pelo Conselho Geral da\nOrdem.\nComo membros vivos da Família dos Servos de\nMaria, vocês assumem o compromisso de viver o\nbatismo à luz desta “Regra de Vida”. Trilhando o\ncaminho da santidade, vocês constroem a igreja-comunhão e anunciam o Evangelho em lugares e\nsituações onde só vocês, leigos, podem testemunhar\nCristo, filho de Maria e primogênito entre muitos\nirmãos. Como Maria, levando aos irmãos e irmãs a\nPalavra que salva e colocando-se ao lado dela aos pés\ndas infinitas cruzes da humanidade, vocês estarão\nlevando conforto e esperança de libertação, cooperando\ncom a missão evangelizadora da Igreja.\nA presente Regra, ora aprovada pela Sé\nApostólica, entrará em vigor dia 15 de agosto de 1995,\nna solenidade da Assunção de Nossa Senhora ao céu, e\ndia em que, segundo a tradição, nossos Primeiros Pais\nchegaram a Monte Senário.\nFazemos votos que no seio das comunidades\ncristãs e das suas fraternidades seculares, vocês sigam\nsempre o caminho de fé e de amor da Virgem do\nMagnificat. Assim fazendo, vocês poderão\ncompartilhar as “maravilhas” que o Senhor fez em\nMaria e um dia juntar-se a Ela no céu, onde reina\ngloriosa e intercede benigna por todos os seus Servos.\nAlegrem-se, pois, e procurem atrair outros para\ncompartilhar a vida de suas fraternidades. Propaguem\nseu carisma de unidade e de harmonia fraterna na\nIgreja e neste mundo tão carente de união, de paz e de\ncompreensão mútua.\nRoma, 4 de maio de 1995, festa de São Peregrino\nLaziosi, OSM e 650° aniversário de sua morte.\nfrei Reinhold M. Bodner, osm\nsecretário da Ordem\nDecreto de Aprovação\nCongregação dos Institutos de Vida\nConsagrada e das Sociedades de Vida\nApostólica\nProt. n. S. 48-1/95\nO Prior Geral da Ordem dos Servos de Maria,\ncom o consenso do seu Conselho, encaminhou à Sé\nApostólica pedido de aprovação da “Regra de Vida” da\nOrdem Secular dos Servos de Maria, revista segundo o\nespírito do Concílio Vaticano II e as normas do Código\nde Direito Canônico.\nA Congregação dos Institutos de Vida\nConsagrada e das Sociedades de Vida Apostólica, vista\na exposição de motivos e estudado atentamente o texto\nem questão, segundo as normas do Direito, com o\npresente decreto aprova e confirma a presente Regra de\nVida, redigida em língua inglesa, conforme exemplar\nguardado nos arquivos deste Dicastério.\nOs membros da Ordem Secular dos Servos de\nMaria, trilhando o caminho dos Sete Santos\nFundadores da Ordem, procurem viver uma vida cristã\nfiel e íntegra e, com renovado ardor, busquem, dia após\ndia, a perfeição do seu estado de vida.\nRevogam-se as disposições em contrário.\nDado em Roma, em 29 de abril de 1995\nEduardo cardeal Martínez Somalo\nPrefeito\nFrancisco Xavier Errázuriz Ossa\nsecretário\nA Ordem Secular na História dos Servos de\nMaria\nAs Constituições da nossa Ordem dizem que “o\nideal dos Servos de Maria suscitou ao redor de nossas\ncomunidades ou associou à Ordem várias famílias ou\ngrupos que, como expressões particulares de vida\nconsagrada ou laical, participam da nossa mesma\nvocação” (art. 15).\nEntre essas expressões particulares está a Ordem\nSecular, até recentemente chamada Ordem Terceira.\nTendo a Ordem nascido de um grupo de sete leigos\nflorentinos, não nos admira que a raiz mais profunda da\nOrdem Secular se confunda e se identifique com a\norigem da Ordem mesma. Todavia, como expressão\nparticular no âmbito da nossa família, a Ordem Secular\nfoi-se configurando aos poucos até assumir um perfil\npróprio. O patrimônio espiritual, porém, foi sempre o\ndas origens, assim como foi vivido pelos Sete\nFundadores e pelos Primeiros Pais, na esteira de uma\nexperiência anterior muito difundida no século XIII: a\ndos Irmãos da Penitência.\nA Legenda sobre as origens da Ordem, citando\num texto anterior, assim fala a respeito dos nossos\nPrimeiros Pais: “Temendo suas imperfeições,\nhumildemente decidiram colocar a si mesmos e seus\ncorações, com toda devoção, aos pés da Rainha dos\ncéus, para que Ela, como mediadora e advogada, os\nsuprindo Ela, com sua grande caridade, as imperfeições\ndeles, lhes obtivesse, misericordiosa, a fecundidade de\nméritos”.\nAinda segundo a Legenda, a experiência de\nnossos Primeiros Pais em Monte Senário caracterizou-se por um estilo de vida simples e, ao mesmo tempo,\nprofundo de vida cristã. Todos os que acorriam a\nMonte Senário “viam que eles não encobriam\nfalsamente seus sentimentos, nem simulavam como\nverdadeiras as coisas falsas, nem como falsas as\nverdadeiras. Viam-nos, pelo contrário, como eles\nverdadeiramente eram: simples, nada faziam por\nostentação, exprimiam com palavras seus sentimentos,\namavam a verdade, evitavam a mentira, distribuíam\ngratuitamente seus bens, sofriam com a maldade antes\nque praticá-la, não se vingavam da ofensa recebida e\nconsideravam um ganho sofrer injúrias por amor à\nverdade”.\nEsses textos primitivos descrevem o espírito do\nque viria a ser no futuro a Ordem secular dos Servos de\nMaria.\nLogo, porém, nossos Primeiros Pais e seus\nseguidores criaram comunidades específicas de\npessoas consagradas e, em poucas décadas, deram vida\nà Ordem dos Servos de Maria que, em 1304, foi\noficialmente aprovada pelo papa Bento XI.\nSabemos que desde as origens houve indivíduos\nou grupos, homens e mulheres, que, ligados aos nossos\nconventos, compartilhavam, como leigos, a vida e a\nespiritualidade dos frades Servos de Maria.\nÉ sintomático a figura de Henrique ou Arrigo de\nSanta Maria de Cafaggio, ligou-se como oblato à igreja\nde Santa Maria de Cafaggio, em Florença. Apesar\ndisso, nada nos autoriza a dizer que houvesse então\numa Regra comum para esses oblatos e oblatas, por\nmais simples que fosse.\nO início por assim-dizer oficial da Ordem\nTerceira dos Servos de Maria é atribuída à bula Sedis\nApostolicae Providentia do papa Martinho V,\npromulgada em 16 de março de 1424. Essa deferência\ndo papa Martinho V em favor dos Servos de Maria\ntalvez se deva ao fato de ele, quando era cardeal Odão\nColonna, ter sido protetor da Ordem de 1407 a 1418.\nO nome mais comum da futura Ordem Terceira\nera Associação ou Companhia dos Servos de Maria.\nEsse nome aparece no final do século XV. Uma prova\ndisso é um livreto de Nicolau Manetti di Pistoia, que\npode ser considerado como o primeiro manual da\nOrdem Terceira.\nA partir do final do século XVI e no início do\nséculo XVII, os priores gerais mais contribuíram para\no crescimento da Ordem Terceira. Embora tendo vários\nnomes, como Associação ou Companhia dos Servos de\nMaria, ela distinguia-se claramente das confrarias.\nNo final do século XIX, com a retomada da\nOrdem subsequente às supressões impostas pelos\ngovernos liberais da Itália, a Ordem Terceira voltou a\ncrescer. Dois escritos do papa Leão XIII modificaram\na antiga Regra de Martinho V. No entanto, só em 1925\nfoi publicada a nova Regra. A esta seguiu-se outra,\ncomposta por iniciativa do prior geral frei Afonso M.\nMontà e aprovada pela Sagrada Congregação dos\nReligiosos em 1º de maio de 1966.\nNa esteira do Concílio Vaticano II, os Servos de\nMaria iniciaram um processo de revisão de suas\nConstituições. O novo texto, aprovado no capítulo\ngeral extraordinário de Majadahonda (Madri), em\n1968, e revisto parcialmente nos capítulos gerais\nseguintes, foi finalmente aprovado pela Sé Apostólica\nem 1987.\nCom relação à Ordem Secular, o Conselho Geral\nda Ordem nomeou uma comissão especial encarregada\nde consultar os membros da Ordem Secular e de ajudá-los na revisão de sua Regra de Vida. Concluído o\ntrabalho, o texto da nova Regra foi aprovado\nexperimentalmente pelo Conselho Geral em outubro de\n1982. Em seguida, a pedido do capítulo geral de 1989,\no Secretariado Geral da Ordem Secular voltou a\nconsultar as bases em vista da redação final do texto a\nser submetida à aprovação da Sagrada Congregação\ndos Institutos de Vida Consagrada e das Sociedades de\nVida Apostólica.\nA presente edição da Regra de Vida da Ordem\nSecular dos Servos de Maria foi aprovada pela Sé\nApostólica em 29 de abril de 1995.\nAo longo de sua história, a Ordem Secular dos\nServos de Maria contou em suas fileiras com muitos\nirmãos e irmãs que se distinguiram por sua santidade,\npelo apego à Família Servita e pela vivência do nosso\ncarisma. Eles são testemunhas vivas e motivo de\nesperança para toda a nossa família.", "chapters": [{"roman": "I", "title": "A Ordem dos Servos de Maria", "text": "1. A Ordem dos Servos de Maria, nascida como\nexpressão de vida evangélico-apostólica, é uma\ncomunidade de homens reunidos em nome do Senhor\nJesus.\nMovidos pelo Espírito, comprometemo-nos, como\nnossos Primeiros Pais, a testemunhar o evangelho em\ncomunhão fraterna e a colocar-nos a serviço de Deus e\ndos seres humanos, inspirando-nos constantemente em\nMaria, Mãe e Serva do Senhor.\n2. Para servir ao Senhor e aos irmãos, os Servos de\nMaria, desde as origens, dedicaram-se à Mãe de Deus,\na Maria, desde as origens, dedicaram-se à Mãe do\nAltíssimo.\nA Ela se voltaram no seu caminho para Cristo e na\nmissão de anunciá-lo aos seres humanos. Do “sim” da\nhumilde serva do Senhor aprenderam a acolher a\nPalavra de Deus e a estar atentos à voz do Espírito; da\nparticipação da Mãe na obra redentora do Filho, servo\nsofredor de Javé, foram induzidos a compreender e\naliviar os sofrimentos humanos.\n3. Sensíveis aos apelos da Igreja, queremos, através do\nestudo, conhecer sempre melhor a Virgem Maria, Mãe\nde Deus e dos seres humanos, e sua missão no mistério\nda Salvação.\nVendo nela o fruto mais sublime da Redenção,\napoiamos com nossas energias as exigências\nlibertadoras dos indivíduos e da sociedade.\nConscientes da divisão entre os cristãos, empenhamo-nos para que a Filha de Sião seja para todos sinal de\nunidade. Às pessoas inseguras, propomos como\nexemplo de confiança dos filhos de Deus, a mulher\nhumilde que pôs no Senhor sua esperança.\n4. Inspirando-se constantemente em Maria, Mãe e\nServa do Senhor, vários institutos religiosos e grupos\nleigos nasceram à sombra das comunidades dos Servos\nde Maria, como expressões particulares de vida\nconsagrada ou laical. Outros institutos e grupos já\nexistentes, atraídos pelo mesmo ideal, agregaram-se à\nOrdem. Cada um deles, quer seja religioso ou leigo,\nvive à sua maneira a mesma vocação que é comum a\ntodos."}, {"roman": "II", "title": "A Ordem Secular dos Servos de Maria e a Vida da Fraternidade", "text": "5. A Ordem Secular dos Servos de Maria congrega\nhomens e mulheres que, unidos pela consagração\nbatismal e movidos pelo Espírito, querem engajar-se no\nserviço a Cristo e aos irmãos deste mundo, inspirando-se em Maria, Mãe e Serva do Senhor. Como membros\nleigos ou seculares da Ordem dos Servos de Maria,\ncomprometem-se, em sua vida familiar e social, a\nseguir o caminho trilhado pelos Sete Santos\nFundadores da Ordem.\n6. Composta de homens e mulheres que vivem sua\nconsagração batismal no mundo, a Ordem Secular é\numa das expressões da mesma vocação da Família dos\nServos de Maria. É parte integrante da Família Servita\ne, como tal, compartilha seus mesmos ideais, o mesmo\ncompromisso de vida evangélico-apostólica e uma\nparticular devoção à Mãe de Deus.\n7. Como membros seculares da Ordem dos Servos de\nMaria, estes irmãos e irmãs são autênticas testemunhas\nda origem laical da nossa Ordem. De fato, foi como\nleigos que os Sete Primeiros Pais iniciaram sua vida\ncomunitária, unidos na oração e no serviço à bem-aventurada Virgem Maria.\n8. Na Igreja, povo santo de Deus, a vocação do irmão e\nda irmã secular dos Servos de Maria é um chamado\nespecial. Comporta um convite gratuito de Deus e uma\nresposta consciente e livre do vocacionado, o qual, ao\ndoar-se, descobre a presença maternal de Maria.\n9. Acolhendo o dom da vocação, que tem suas raízes\nna consagração batismal, o Servo de Maria da Ordem\nSecular compromete-se a seguir a Cristo e a viver\nplenamente o mandamento evangélico do amor.\n10. Os irmãos e irmãs da Ordem secular são homens e\nmulheres que, apoiando-se mutuamente em sua vida\nmatrimonial, familiar e social, plenamente inseridos no\nmundo, esforçam-se para buscar a santidade segundo o\nespírito da Ordem, seguindo suas diretrizes e\nobservando a Regra própria.\n11. Os Servos de Maria da Ordem Secular assumem o\ncompromisso de fazer sua a experiência dos Sete\nPrimeiros Pais, que viveram em comunhão fraterna\npara poderem melhor servir a Deus, à Virgem Maria e\naos irmãos e irmãs. Reunidos em nome do Senhor,\ndescobrem na fraternidade a presença do Senhor e\nencontram nela o apoio necessário para responder ao\nseu chamado específico à santidade.\n12. Os irmãos e irmãs seculares, mediante a escuta da\nPalavra de Deus e a oração, alimentam sua vocação\ncristã e sua missão na Igreja e no mundo. Como\nmembros vivos da comunidade eclesial, esforçam-se\npara conhecer e seguir seus ensinamentos na vida e no\napostolado.\n13. Segundo o espírito da Ordem, os irmãos e irmãs\nseculares inspiram-se constantemente em Maria, Mãe\ne Serva do Senhor. Eles a têm como imagem-guia, que\nos leva a viver uma vida simples, serviçal e voltada\npara Deus. E a se consagram inteiramente, venerando-a de modo especial como Virgem das Dores. Mediante\no estudo e a oração, buscam conhecer mais\nprofundamente a Virgem Maria e sua missão no\nmistério da salvação.\n14. Através da promessa, os irmãos e irmãs da Ordem\nsecular assumem livremente o compromisso de\nfidelidade à sua vocação e de manter-se intimamente\nunidos à Ordem.\n15. À imitação dos primeiros cristãos, que tinham “um\nsó coração e uma só alma”, os irmãos e irmãs da Ordem\nSecular reúnem-se sob o signo da comunhão fraterna,\nno intuito de se apoiarem uns aos outros no caminho\ncomum que os leva à perfeição cristã e ao serviço de\namor a todos os seres humanos.\n16. Todos participem assiduamente dos encontros\nperiódicos que celebram a vida da fraternidade secular.\nCom simplicidade, compartilhem suas idéias e\nexperiências.\n17. A fraternidade secular reúne-se para a leitura e a\nreflexão comum da Palavra de Deus e para o estudo da\nRegra e de outros temas humanos, sociais e religiosos\nconcernentes à vida dos Servos de Maria.\n18. A fraternidade secular mantenha-se intimamente\nunida à Igreja local e à comunidade religiosa da Família\nServita, cuja espiritualidade partilha e com a qual\ncolabora no serviço apostólico.\n19. Os Servos de Maria da fraternidade secular, na\nmedida do possível, participem dos momentos de\noração da comunidade religiosa de frades ou irmãs à\nqual está ligada e, quando convidados, também dos\nencontros de renovação espiritual, do capítulo e da\nrefeição comum.\n20. A fraternidade mantenha estreita ligação com os\nirmãos e irmãs que, por motivos particulares, não\npodem participar dos encontros do grupo. Encoraje-os\ne sustente-os na comunhão fraterna e no crescimento\nreligioso. Da mesma forma, mantenha laços de\ncomunhão, de espírito de família e de união com os\ndemais institutos e grupos que compartilham a mesma\nvocação de Servos de Maria e com os quais formam\numa só família. Dê particular atenção à comunicação e\nà colaboração com as outras associações leigas da\nOrdem.\n21. Segundo o espírito das bem-aventuranças, a\nfraternidade secular pratique a comunhão de bens\ncomuns, e ajudando os irmãos e irmãs que se\nencontram em dificuldades financeiras."}, {"roman": "III", "title": "Oração", "text": "22. A oração é um dever fundamental de todo cristão.\nMas para os Servos de Maria da Ordem Secular, que\nquerem seguir a Cristo e observar os seus\nensinamentos, é um compromisso prioritário, que faz\ncrescer a fé e a esperança e ajuda a viver em plenitude\no mandamento do amor.\n23. Saibam os irmãos e irmãs seculares que, para\nmanter-se sempre na presença de Deus, é necessária a\noração pessoal, silenciosa, oculta, da qual o próprio\nJesus é exemplo admirável.\n24. A oração é o encontro com Deus fundado na fé.\nNisso, a Virgem Maria – eminente exemplo de criatura\norante – é apoio e guia seguro para o irmão e irmã da\nsecular.\n25. Fiéis à sua vocação, os Servos de Maria seculares\ntenham em devido apreço a oração comunitária. Junto\ncom seus irmãos e irmãs procurem descobrir as\nriquezas da Palavra de Deus e rezem pelas\nnecessidades de toda a humanidade e do mundo.\n26. Entre as várias formas de oração, a liturgia\nsobressai como ação sagrada por excelência. Os Servos\nde Maria da Ordem Secular participem ativamente da\nvida litúrgica e sacramental da Igreja.\n27. Na Eucaristia, os irmãos e as irmãs da fraternidade\nsecular atualizam a Páscoa do Senhor e fortalecem os\nlaços de amor que os unem entre si e com todos os seres\nhumanos. A Eucaristia é o sinal sacramental da\ncomunhão e a mais alta expressão de oração.\n28. Os irmãos e irmãs seculares participem ativamente\nda Missa, dando preferência à da comunidade religiosa\nlocal à qual estão ligados. Procurem com frequência a\ncelebração da Liturgia das Horas, pela manhã e à tarde.\n29. Segundo a tradição da Ordem, a fraternidade\nsecular venere a Virgem Maria com atos de particular\ndevoção, como a saudação angélica, a Vigília de Nossa\nSenhora, a Coroa de Nossa Senhora das Dores. Celebre\ncomo festas de família as principais festas litúrgicas da\nOrdem e da Igreja local, a memória de Nossa Senhora\ndas Dores, bem como as solenidades e as memórias dos\nsantos e santas da Ordem.\n30. Os Servos de Maria seculares lembrem\nfrequentemente os irmãos e irmãs defuntos,\nimplorando para eles a misericórdia do Senhor. No dia\nda morte e dos funerais de um irmão ou irmã, sejam\nsolidários com a dor dos familiares e façam as orações\nde sufrágio.\n31. É dever da fraternidade secular programar dias e\nperíodos de recolhimento, dos quais todos os irmãos e\nirmãs procurem participar."}, {"roman": "IV", "title": "Penitência e Conversão", "text": "32. Para os irmãos e irmãs da Ordem Secular, que\nassumiram o compromisso de viver em plenitude o\nmandamento da caridade, a penitência é um valor\nevangélico e um instrumento de conversão.\n33. Segundo o exemplo dos nossos Primeiros Pais e a\ntradição da Ordem, a penitência consiste, sobretudo, na\ncaridade entendida como aceitação mútua e serviço\nfraterno.\n34. Cientes de que o seguimento de Cristo exige um\nesforço constante para cumprir a vontade de Deus, os\nirmãos e irmãs seculares mantenham-se alertas e\naproveitem de todas as ocasiões que diariamente se\nlhes apresentam para praticar a penitência,\nconsiderando-as como sinal da graça e convite à\nconversão. Façam frequente uso do sacramento da\nreconciliação e valorizem as obras de misericórdia, a\nsobriedade e, em particular, os tempos litúrgicos da\nQuaresma e do Advento."}, {"roman": "V", "title": "Testemunho de Pobreza", "text": "35. Segundo o exemplo de Maria, pobre e humilde\nserva do Senhor, os irmãos e irmãs seculares esforcem-se para viver a bem-aventurança evangélica que diz:\n“Felizes os pobres de coração, porque deles é o reino\nde Deus”.\n36. Dedicando-se com afinco ao trabalho, levando uma\nvida simples e austera, sendo sensíveis diante das\nnecessidades do próximo e ajudando os mais\nnecessitados, os irmãos e irmãs seculares, como\nindivíduos e como fraternidade, dão testemunho do seu\namor a Cristo pobre e anunciam aos homens e mulheres\nde hoje que Deus é o único bem necessário e que só ele\npode satisfazer plenamente o coração humano."}, {"roman": "VI", "title": "Apostolado", "text": "37. Fiéis à sua vocação, os irmãos e irmãs seculares\nprocuram irradiar no mundo o amor a Cristo e, a\nexemplo de Maria, sejam testemunhas vivas de doação\naos outros.\n38. Conscientes de que a família é o alicerce da\nsociedade civil e laical, os irmãos e irmãs seculares\npriorizam o apostolado familiar e o testemunho de vida\nda família cristã, na qual o amor mútuo, o respeito aos\npais e o zelo na educação cristã dos filhos, sejam o alvo\nprincipal da oração e do empenho de fraternidade.\n39. Como membros da Igreja e inseridos no mundo, os\nirmãos e irmãs seculares compartilham suas angústias\ne aspirações e, movidos pelo amor a Deus, contribuem\npara a construção de um mundo novo, iluminado pelos\nvalores evangélicos.\n40. Os irmãos e irmãs seculares procurem viver, no seu\ndia-a-dia, a vida do Espírito na oração e em seus\nserviços pastorais, na vida conjugal e familiar, no\ntrabalho e nos momentos de lazer, para que tudo isso se\ntransforme em sacrifício agradável a Deus por Jesus\nCristo.\n41. Os irmãos e irmãs seculares, parcelas vivas da\nfraternidade, colaborem no cumprimento dos\ncompromissos pastorais assumidos pelo grupo, como\nresposta às necessidades do ambiente em que vivem e\nda Igreja local. Colaborem também, segundo suas\ncapacidades, nos trabalhos e serviços eclesiais da\ncomunidade religiosa e paroquial.\n42. Devotos de Nossa Senhora das Dores, os irmãos e\nirmãs seculares aprendam a atender e servir com\ncarinho os doentes, os moribundos e os mais\nnecessitados moral ou fisicamente. Neste compromisso\nde serviço, a presença de Maria ao pé da cruz seja sua\nimagem-guia. Posto que o Filho do Homem continua\nainda crucificado nos seus irmãos e irmãs, os membros\nda Ordem Secular querem estar presentes ao lado dela\naos pés das infinitas cruzes da humanidade.\n43. A fraternidade secular apoie e ajude a Ordem na\nanimação vocacional, no serviço apostólico e, em\nmodo particular, nos seus compromissos missionários."}, {"roman": "VII", "title": "Formação", "text": "44. A vocação do irmão e irmã secular desenvolve-se\nno interior da fraternidade e em comunhão com toda a\nFamília Servita. Para sua formação permanente, os\nirmãos e irmãs seculares procurem estudar com atenção\nos documentos oficiais da Igreja e da Ordem.\n45. A fraternidade secular propicia aos irmãos e irmãs\na experiência da comunhão de vida e a ajuda constante;\npor sua vez, a comunidade da Família Servita lhes\noferece as riquezas da Igreja e da Ordem.\n46. Os irmãos e irmãs seculares sabem que o caminho\nque leva ao amadurecimento pleno de sua vocação\ncomporta esforço pessoal e uso efetivo dos próprios\ndons e talentos para servir e preste um serviço de\nanimação espiritual.\n47. A Virgem Maria viveu nesta terra uma vida normal\ncomo todos, dedicada à família e ao trabalho, e sempre\nse manteve intimamente unida ao seu Filho,\ncooperando de maneira singular com a obra da\nSalvação. Ela é, portanto, modelo de vida para todos os\nServos de Maria da Ordem Secular.\nIngresso na Fraternidade Secular"}, {"roman": "VIII", "title": "Admissão", "text": "48. Podem ser admitidos na Ordem Secular dos Servos\nde Maria todos os que manifestam o desejo sincero de\ncompartilhar o ideal da nossa Ordem e se\ncomprometem a viver e testemunhar, em sua condição\nfamiliar e social, os valores humanos e evangélicos da\nvida cristã, e a honrar e imitar de modo especial a\nVirgem Maria, segundo o espírito da Ordem.\n49. Para ser admitido na Ordem Secular, o candidato\nfará pedido por escrito ao conselho da fraternidade\nsecular, ao qual compete a decisão.\n50. O ingresso na fraternidade celebra-se segundo o\nritual próprio da Ordem Secular dos Servos de Maria.\n51. Ao ser admitido, o candidato inicia sua experiência\nde vida na fraternidade secular, mediante o estudo e a\nprática da Regra, de modo que se possa avaliar a\nautenticidade de sua vocação."}, {"roman": "IX", "title": "Prova ou Noviciado", "text": "52. Prova ou Noviciado é o período de tempo que vai\ndesde a admissão até a promessa. Tenha normalmente\num ano de duração.\n53. Durante a prova ou noviciado, o candidato, sob a\norientação do formador responsável e do assistente,\nprocure:\n– descobrir e assimilar progressivamente a vocação\nespecífica do leigo na Igreja e os aspectos próprios da\nfraternidade secular servita;\n– estudar a Regra e os Estatutos da Ordem Secular\nServita;\n– estudar e assimilar a doutrina sobre a Virgem Maria\nno mistério de Cristo e da Igreja;\n– conhecer os aspectos essenciais da história e a\nespiritualidade da Ordem dos Servos de Maria.\n54. Por motivos justos e de acordo com a capacidade\nde assimilação e de decisão do candidato, o tempo de\nProva pode ser abreviado ou prolongado, a critério do\nconselho da fraternidade secular."}, {"roman": "X", "title": "Promessa", "text": "55. A promessa é o ato pelo qual o candidato renova\nsua consagração batismal, comprometendo-se a vivê-la\nsegundo o espírito da Ordem dos Servos de Maria, em\ncomunhão fraterna com todas as comunidades da\nFamília Servita e segundo a Regra e os Estatutos\npróprios da Ordem Secular.\n56. A promessa incorpora para sempre o candidato à\nOrdem Secular e o torna participante da vida de toda a\nFamília Servita.\n57. Para ser admitido à promessa, o candidato fará\npedido por escrito ao conselho da fraternidade secular.\nO candidato deve ter pelo menos 18 anos de idade.\n58. O rito da promessa segue as normas e a fórmula\nprescritas pelo ritual próprio da Ordem Secular dos\nServos de Maria e é presidido pelo prior da comunidade\nreligiosa ou por um delegado da Ordem.\n59. Por motivos justos e válidos, o conselho da\nfraternidade secular pode dispensar temporária ou\ndefinitivamente da promessa ou mesmo demitir um\nirmão ou irmã que fez a promessa, após expor os\nmotivos ao interessado e ouvir suas razões.\nOrganização da Fraternidade Secular"}, {"roman": "XI", "title": "Organização", "text": "60. A Ordem Secular dos Servos de Maria compõe-se\nde fraternidades locais que, unidas pelo mesmo ideal de\nvida, formam a fraternidade internacional.\n61. As fraternidades seculares podem organizar-se em\ngrupos de fraternidades locais, regionais ou nacionais.\n62. A fraternidade ou o grupo de fraternidades, sob a\norientação dos respectivos priores ou conselhos,\nprograma sua vida interna.\n63. A fraternidade secular mantém-se unida à Ordem\natravés do assistente adrede designado."}, {"roman": "XII", "title": "Reconhecimento e Ereção Canônica da Fraternidade", "text": "64. a) Em se tratando de um grupo criado junto a uma\ncomunidade de frades, compete ao capítulo conventual\ndesta reconhecê-lo como autenticamente servita e\napoiar o seu pedido de ereção canônica.\nb) Qualquer outra entidade da Família Servita\n(mosteiro, Congregação religiosa ou Instituto Secular)\npode reconhecer a autenticidade de um grupo nascido\na seu redor, bem como apoiar seu pedido de ereção\ncanônica.\nc) O reconhecimento de um grupo criado fora do\nâmbito das comunidades da Família Servita compete,\nconforme o caso, ao conselho vicarial, provincial ou\ngeral.\n65. A fraternidade da Ordem Secular é erigida\ncanonicamente por decreto do Prior Geral da Ordem.\n66. Para que uma fraternidade possa ser erigida\ncanonicamente, far-se-á pedido por escrito. Tratando-se de fraternidade nascida fora do âmbito de uma\ncomunidade religiosa da Família Servita, além do\npedido escrito, exige-se a autorização do Ordinário do\nlugar.\n67. O secretário geral da Ordem Secular e dos Grupos\nLeigos deve ser devidamente informado sobre a ereção\ncanônica de uma fraternidade."}, {"roman": "XIII", "title": "Governo", "text": "68. Prior Geral\nO Prior Geral da Ordem, sinal de unidade de toda a\nFamília Servita, tem autoridade sobre toda a Ordem\nSecular dos Servos de Maria e a exerce em espírito de\nserviço, respeitando sua autonomia.\n69. Secretário Geral\n1. O secretário geral é nomeado pelo conselho geral da\nOrdem. É sua missão principal animar e coordenar a\nvida das fraternidades em nível geral.\n2. Em colaboração com os membros do secretariado\ngeral e com os assistentes nos diversos níveis, o\nsecretário geral leve ao conhecimento das fraternidades\nseculares as diretrizes espirituais e pastorais da Igreja\nuniversal e da Ordem, bem como as atividades e as\nexperiências mais significativas da Ordem Secular no\nmundo.\n70. Prior(a) da Fraternidade\n1. O prior ou priora, primeiro entre os irmãos e irmãs,\npreside à fraternidade como um serviço de caridade. É\nresponsável pela fraternidade junto com o conselho e\ncom cada membro da mesma. No exercício do seu\ncargo, lembre-se de dar testemunho de Cristo, que veio\nnão para ser servido, mas para servir e aumentar a vida\ndos seus.\n2. É dever do(a) prior(a):\n– convocar as reuniões da fraternidade e do conselho e\npresidi-las;\n– promover e animar os compromissos espirituais e\napostólicos da fraternidade;\n– zelar pela observância da Regra e dos Estatutos;\n– colaborar com o assistente e com os oficiais da\nfraternidade.\n71. O prior ou priora é eleito segundo as normas dos\nEstatutos próprios da fraternidade secular.\n72. Conselho\n1. Toda fraternidade secular terá um conselho,\ncomposto do prior ou priora e de pelo menos três\nconselheiros eleitos pela fraternidade mesma.\n2. Compete ao conselho:\n– colaborar com o prior na coordenação e animação da\nfraternidade;\n– aceitar um candidato na fraternidade admiti-lo à\npromessa;\n– dispensar da promessa;\n– demitir, quando necessário, um membro da\nfraternidade, após ouvir o interessado.\n73. Assistente\n1. Toda fraternidade secular ou um grupo de\nfraternidades terá um assistente nomeado pela\nautoridade competente da Família Servita. Se o\nassistente não for competente da Ordem, sob proposta\nda fraternidade secular local, e confirmado pelo\nOrdinário do lugar.\n2. O assistente pode ser um irmão ou irmã da Família\nServita (frade, monja, freira, membro de Instituto\nSecular) ou um presbítero membro da nossa Ordem\nSecular ou então outro presbítero.\n3. O assistente seja competente e disponível e, junto\ncom os irmãos e irmãs da fraternidade, cujo caminho\nde fé compartilha, procure conhecer e viver mais\nprofundamente a vocação específica do Servo de Maria\nsecular.\n4. O assistente promova, entre os membros da\nfraternidade, o espírito da Família Servita e preste um\nserviço de animação espiritual.\n74. Secretário\n1. Toda fraternidade terá um secretário.\n2. Cabe ao secretário:\n– lavrar a ata das reuniões da fraternidade e do\nconselho;\n– manter em dia o registro das Admissões e das\nPromessas;\n– guardar e manter atualizado o fichário da\nfraternidade;\n– manter contato com os irmãos e irmãs impedidos de\nparticipar das reuniões.\nEstatutos Próprios da Fraternidade\nSecular\n75. Toda fraternidade secular ou grupo de fraternidades\nterá um Estatuto próprio, por ela mesma aprovado, para\na regulamentação prática das normas da presente\nRegra.\n76. O Estatuto próprio deverá regulamentar:\n– o sistema eletivo e a duração do mandato do prior ou\npriora;\n– o sistema eletivo e a duração do mandato dos\nmembros do conselho;\n– o eventual aumento do número de conselheiros;\n– o número de conselheiros, se forem necessários mais\nde três;\n– o número, as atribuições, o sistema eletivo e a\nduração do mandato dos outros oficiais da fraternidade;\n– outros deveres do secretário."}]}, "daily": {"anjo": "D. O anjo do Senhor anunciou a Maria.\nT. E Ela concebeu do Espírito Santo.\n   Ave Maria, cheia de graça, o Senhor é convosco, bendita sois vós entre as mulheres e bendito é o fruto do vosso ventre, Jesus. Santa Maria, Mãe de Deus, rogai por nós pecadores, agora e na hora da nossa morte. Amém.\n\nD. Eis aqui a serva do Senhor.\nT. Faça-se em mim segundo a vossa Palavra.\n   Ave Maria...\n\nD. E o Verbo Divino se fez carne.\nT. E habitou entre nós.\n   Ave Maria...\n\nD. Rogai por nós, Santa Mãe de Deus.\nT. Para que sejamos dignos das promessas de Cristo.\n\nOremos\n\nD. Derramai, Senhor, a vossa graça em nossas almas, a fim de que nós que, pela anunciação do anjo, viemos ao conhecimento da Encarnação do vosso Filho, cheguemos, por sua paixão e morte, à glória da ressurreição. Pelo mesmo Cristo Senhor nosso.\nT. Amém!\n\nD. Glória ao Pai, ao Filho e ao Espírito Santo.\nT. Como era no princípio, agora e sempre. Amém.", "rainha": "D. Rainha do céu, alegrai-vos, aleluia!\nT. Pois o Senhor que merecestes trazer em vosso seio, aleluia!\n\nD. Ressuscitou como disse, aleluia!\nT. Rogai a Deus por nós, aleluia!\n\nD. Alegrai-vos e exultai, ó Virgem Maria, aleluia!\nT. Porque o Senhor ressuscitou verdadeiramente, aleluia!\n\nOremos\n\nD. Ó Deus que, na gloriosa ressurreição do vosso Filho, destes alegria ao mundo inteiro, por intercessão da Virgem Maria, concedei-nos gozar a alegria perene da vida eterna. Por Cristo nosso Senhor.\nT. Amém!"}, "devotions": {"vigilia": {"formula1": "Primeira fórmula\n Santa Maria,\n Senhora Dos Seus Servos\nSalmodia\n\n1ª Ant. Bendita és tu entre as mulheres e bendito o fruto\n do teu ventre.\n\n SALMO 8\n Majestade de Deus e dignidade do homem\n\"O Todo-Poderoso fez grandes coisas por mim\" (Lc\n1,49).\n– 2Ó Senhor nosso Deus, como é grande *\nvosso nome por todo o universo!\n– Desdobrastes nos céus vossa glória *\ncom grandeza, esplendor, majestade.\n= 3O perfeito louvor vos é dado †\npelos lábios dos mais pequeninos, *\nde crianças que a mãe amamenta.\n– Eis a força que opondes aos maus, *\nreduzindo o inimigo ao silêncio.\n– 4Contemplando estes céus que plasmastes *\ne formastes com dedos de artista;\n\n– vendo a lua e estrelas brilhantes, *\n perguntamos: ‘Senhor, que é o homem,\n– para dele assim vos lembrardes *\ne o tratardes com tanto carinho?’\n– 6Pouco abaixo de Deus o fizestes, *\ncoroando-o de glória e esplendor;\n– 7vós lhe destes poder sobre tudo, *\nvossas obras aos pés lhe pusestes:\n– 8as ovelhas, os bois, os rebanhos, *\ntodo o gado e as feras da mata;\n– 9passarinhos e peixes dos mares, *\ntodo ser que se move nas águas.\n– 10Ó Senhor nosso Deus, como é grande *\nvosso nome por todo o universo!\n1ª Ant. Bendita és tu entre as mulheres e bendito o fruto\n do teu ventre.\n2ª Ant. Santa Mãe de Deus, como aroma precioso\n emanas suave perfume.\n\n SALMO 18\n Hino ao Criador do universo e Senhor da lei\n\n\"Quando o Verbo se fez carne, como um esposo, uniu-\nse à natureza humana: tálamo das núpcias foram as\nentranhas da Virgem Maria\" (Santo Agostinho)\n– 2Os céus proclamam a glória do Senhor, *\ne o firmamento, a obra de suas mãos;\n– 3o dia ao dia transmite esta mensagem, *\na noite à noite publica esta notícia.\n– 4Não são discursos nem frases ou palavras, *\nnem são vozes que possam ser ouvidas;\n– 5seu som ressoa e se espalha em toda a terra, *\nchega aos confins do universo a sua voz.\n– 6Armou no alto uma tenda para o sol; *\nele desponta no céu e se levanta\n– como um esposo do quarto nupcial, *\ncomo um herói exultante em seu caminho.\n– 7De um extremo do céu põe-se a correr *\ne vai traçando o seu rastro luminoso,\n– até que possa chegar ao outro extremo, *\ne nada pode fugir ao seu calor.\n\n– 8A lei do Senhor Deus é perfeita, *\nconforto para a alma!\n– O testemunho do Senhor é fiel, *\nsabedoria dos humildes.\n\n– 9Os preceitos do Senhor são precisos, *\nalegria ao coração.\n– O mandamento do Senhor é brilhante, *\npara os olhos é uma luz.\n– 10É puro o temor do Senhor, *\nimutável para sempre.\n– Os julgamentos do Senhor são corretos *\ne justos igualmente.\n– 11Mais desejáveis do que o ouro são eles, *\ndo que o ouro refinado.\n– Suas palavras são mais doces que o mel, *\nque o mel que sai dos favos.\n– 12E vosso servo, instruído por elas, *\nse empenha em guardá-las.\n– 13Mas quem pode perceber suas faltas? *\nPerdoai as que não vejo!\n\n– 14E preservai o vosso servo do orgulho: *\nnão domine sobre mim!\n– E assim puro, eu serei preservado *\ndos delitos mais perversos.\n– 15Que vos agrade o cantar dos meus lábios *\ne a voz da minha alma;\n– que ela chegue até vós, ó Senhor, *\n\nmeu Rochedo e Redentor!\n\n2ª Ant. Santa Mãe de Deus, como aroma precioso\n emanas suave perfume!\n\n3ª Ant. Ao prodígio da tua virgindade elevemos com\n júbilo um hino de alegria!\n\n SALMO 23\n O Senhor entra no seu Templo\n\"As portas do céu abriram-se ao Cristo quando\nassumiu a natureza humana\" (Santo Irineu)\n– 1Ao Senhor pertence a terra e o que ela encerra, *\no mundo inteiro com os seres que o povoam;\n– 2porque ele a tornou firme sobre os mares, *\ne sobre as águas a mantém inabalável.\n\n– 3“Quem subirá até o monte do Senhor, *\nquem ficará em sua santa habitação?”\n= 4“Quem tem mãos puras e inocente coração, †\nquem não dirige sua mente para o crime, *\nnem jura falso para o dano de seu próximo.\n– 5Sobre este desce a bênção do Senhor *\ne a recompensa de seu Deus e Salvador”.\n– 6“É assim a geração dos que o procuram, *\ne do Deus de Israel buscam a face”.\n\n= 7“Ó portas, levantai vossos frontões! †\nElevai-vos bem mais alto, antigas portas, *\na fim de que o Rei da glória possa entrar!”\n= 8Dizei-nos: “Quem é este Rei da glória?” †\n“É o Senhor, o valoroso, o onipotente, *\no Senhor, o poderoso nas batalhas!”\n\n= 9“Ó portas, levantai vossos frontões! †\nElevai-vos bem mais alto, antigas portas, *\na fim de que o Rei da glória possa entrar!”\n= 10Dizei-nos: “Quem é este Rei da glória?” †\n“O Rei da glória é o Senhor onipotente, *\no Rei da glória é o Senhor Deus do universo!”\n3ª Ant. Ao prodígio da tua virgindade, elevemos com\n júbilo um hino de alegria!\nIntrodução às leituras\nD. Ave Maria, cheia de graça, o Senhor é convosco.\nT. Bendita sois vós entre as mulheres e bendito é o fruto\n do vosso ventre, Jesus!\nAbsolvição\n\nD. Pelas preces e méritos da bem-aventurada Virgem\n Maria e de todos os santos, o Senhor nos conduza ao\n Reino dos céus.\nT. Amém!\n\nPrimeira leitura\nL. Invoca sobre mim a bênção do Senhor.\nD. Com seu divino Filho proteja-nos a Virgem Mãe.\nT. Amém!\n\nL. Santa Maria, Virgem das virgens, Mãe e Filha do\n Rei dos reis, dá-nos teu conforto nas dificuldades da\n vida. Por tua misericordiosa intercessão, o Senhor\n nos conceda o prêmio do céu e o reino eterno junto\n com seus eleitos. E tu, Senhor, tem piedade de nós!\nT. Demos graças a Deus!\n\nResponsório\nT. Como poderei louvar-te, Santa Virgem Maria? *\n Aquele que os céus não podem conter, o encerraste\n em teu seio!\nL. Bendita és tu entre as mulheres e bendito é o fruto\n do teu ventre!\nT. Aquele que os céus não podem conter, o encerraste\n em teu seio!\n\nSegunda leitura\nL. Invoca sobre mim a bênção do Senhor.\n\nD. A Virgem imaculada interceda por nós junto ao\n Senhor.\nT. Amém!\nL. Santa Maria, Mãe piedosa, intercede por nós,\n Virgem santa! Apresenta nossas súplicas ao teu Filho\n que, nascido para a nossa salvação, reina agora nos\n céus. Sua misericordiosa graça apague os nossos\n pecados. E tu, Senhor, tem piedade de nós!\nT. Demos graças a Deus!\nResponsório\nT. Feliz és tu, Virgem Maria, pois trouxeste o Criador\n do mundo! * Deste à luz aquele que te criou e\n permaneceste sempre virgem!\nL. Ave, ó cheia de graça, o Senhor é contigo.\nT. Deste à luz aquele que te criou e permaneceste\n sempre virgem!\nTerceira leitura\nL. Invoca sobre mim a bênção do Senhor.\nD. Pela intercessão da Virgem Maria, o Senhor nos\n conceda a paz e a salvação.\nT. Amém!\nL. Santa Mãe de Deus, tu que foste digna de trazer em\n teu seio aquele que o universo não pode conter, acolhe\n a nossa súplica! Tua misericordiosa intercessão nos\n\n obtenha o perdão das culpas e tua maternal presença\n nos conduza à morada da luz, onde com teu Filho\n reinas eternamente. E tu, Senhor, tem piedade de nós!\nT. Demos graças a Deus!\n\nSalve Rainha\n\n Salve, Rainha, Mãe de misericórdia, vida, doçura e\nesperança nossa, salve! A vós bradamos os degredados\nfilhos de Eva. A vós suspiramos, gemendo e chorando\nneste vale de lágrimas. Eia, pois, advogada nossa, esses\nvossos olhos a nós volvei! E depois deste desterro,\nmostrai-nos Jesus, bendito fruto do vosso ventre. Ó\nclemente, ó piedosa, ó doce sempre Virgem Maria!\n\nD. Rogai por nós, santa Mãe de Deus!\nT. Para que sejamos dignos das promessas de Cristo.\n\nOremos\n\nD. Deus onipotente e eterno, que pela cooperação do\n Espírito Santo, preparastes, no corpo e na alma da\n bem-aventurada Virgem Maria, uma habitação digna\n do vosso Filho, fazei que celebrando com alegria sua\n memória, ela nos livre, por sua maternal intercessão,\n de todos os males da vida presente e da morte eterna.\n Por Cristo nosso Senhor.\nT. Amém!\n\n Oração pela Igreja pela Ordem\n Ó Senhor, por vossa misericórdia, dissolvei os\nvínculos dos nossos pecados e, pela intercessão da\nbem-aventurada Virgem Maria, Mãe de Deus, dos\nnossos Sete Santos Pais, do vosso servo São Filipe e de\ntodos os santos, guardai e santificai o papa NN, o nosso\nprior geral NN, a nós vossos servos, nossas\ncomunidades e benfeitores.\n Afastai do mal nossos pais, parentes e amigos e\nenriquecei-os de virtude. Concedei-nos saúde e paz.\nAfastai os inimigos visíveis e invisíveis e purificai-nos\nde todo desejo mundano. Dai serenidade aos ares e\nfertilidade aos campos.\n Libertai o mundo da fome, da guerra e de qualquer\noutro flagelo. Preservai ilesa de toda calamidade esta\ncidade e seus habitantes. Dai vosso amor a nossos\namigos e também a nossos inimigos, e concedei aos\nfiéis defuntos o eterno repouso. Amém!", "formula2": "Segunda fórmula\n Santa Maria\n Serva Do Senhor\nIntrodução\n\nD. Bendita sois vós entre as mulheres\nT. E bendito é o fruto do vosso ventre.\n\nD. Louvai comigo o Senhor pelas maravilhas que fez\n em Maria.\nT. Grandes e admiráveis são as tuas obras, Senhor\n Deus todo-poderoso! Justos e verdadeiros os teus\n caminhos, ó Rei do universo!\n\nHino\n \"Serva humilde eu sou do Senhor,\n em mim se faça segundo disseste\".\n Terra obediente tu és, ó Maria,\n terra que acolhe, que ama e adora.\n Filha querida do povo escolhido,\n santo rebento que brota em flor,\n flor desejada, esperada por todos,\n flor que embeleza o deserto do mundo.\n\n Dia após dia a Igreja repita\n as santas palavras da serva fiel:\n tudo haverá de voltar como outrora,\n quando Deus Pai caminhava no Éden.\n Glória à Trindade, Pai, Filho e Espírito,\n que desde sempre renovam o mundo:\n pois que nos deram uma Virgem e Mãe,\n beleza intacta de toda a criação.\n1ª Ant. Ave, Virgem fiel, mulher da nova aliança,\n primícias do Reino.\n SALMO 110\n Grandes são as obras do Senhor\n\"A minh'alma engrandece o Senhor, pois o Todo-\npoderoso fez em mim grandes coisas\" (Lc 1,46. 49).\n\n– 1Eu agradeço a Deus de todo o coração *\njunto com todos os seus justos reunidos!\n– 2Que grandiosas são as obras do Senhor, *\nelas merecem todo o amor e admiração!\n\n– 3Que beleza e esplendor são os seus feitos! *\nSua justiça permanece eternamente!\n– 4O Senhor bom e clemente nos deixou *\na lembrança de suas grandes maravilhas.\n\n– 5Ele dá o alimento aos que o temem *\ne jamais esquecerá sua Aliança.\n– 6Ao seu povo manifesta seu poder, *\ndando a ele a herança das nações.\n\n– 7Suas obras são verdade e são justiça, *\nseus preceitos, todos eles, são estáveis,\n– 8confirmados para sempre e pelos séculos, *\nrealizados na verdade e retidão.\n\n= 9Enviou libertação para o seu povo, †\nconfirmou sua Aliança para sempre. *\nSeu nome é santo e é digno de respeito.\n\n= 10Temer a Deus é o princípio do saber, †\ne é sábio todo aquele que o pratica. *\nPermaneça eternamente o seu louvor.\n\n1ª Ant. - Ave, Virgem fiel, mulher da nova aliança,\n primícias do Reino.\nOração sálmica\n Nós vos agradecemos, Senhor, porque por meio de\nMaria, vossa serva fiel, nos destes o Mediador da nova\nAliança. Concedei, vos pedimos, cumprir com amor os\n\nvossos preceitos e ser fiéis à vossa Palavra e ao nosso\ncompromisso de serviço. Por Cristo nosso Senhor.\nAmém!\n2ª Ant. Ave, gloriosa Mãe de Cristo, em ti os humildes\n são exaltados, por ti renasce a esperança dos\n pobres.\n SALMO 112\n A glória e a misericórdia do Senhor\n\"Olhou para a humildade de sua serva... Exaltou os\nhumildes\" (Lc 1, 48. 52).\n\n– 1Louvai, louvai, ó servos do Senhor, *\nlouvai, louvai o nome do Senhor!\n– 2Bendito seja o nome do Senhor, *\nagora e por toda a eternidade!\n– 3Do nascer do sol até o seu ocaso, *\nlouvado seja o nome do Senhor!\n– 4O Senhor está acima das nações, *\nsua glória vai além dos altos céus.\n= 5Quem pode comparar-se ao nosso Deus, †\nao Senhor, que no alto céu temo seu trono *\n e se inclina para olhar o céu e a terra?\n– 7Levanta da poeira o indigente *\ne do lixo ele retira o pobrezinho,\n– 8para fazê-lo assentar-se com os nobres, *\nassentar-se com os nobres do seu povo.\n\n– 9Faz a estéril, mãe feliz em sua casa, *\nvivendo rodeada de seus filhos.\n2ª Ant. - Ave, gloriosa Mãe de Cristo, em ti os humildes\n são exaltados, por ti renasce a esperança dos\n pobres.\nOração sálmica\n\nDo nascer ao pôr do sol, louvado seja o vosso nome,\nSenhor, porque escolhestes Maria, mulher humilde e\npobre, para ser a Mãe gloriosa do vosso Filho. Primeira\nentre os remidos, vós a colocastes na Igreja como Mãe\nfeliz de muitos filhos. Por Cristo nosso Senhor. Amém!\n3ª Ant. Ave, mulher da esperança! De ti nasceu a luz do\n mundo, por ti nos veio o Pão da vida.\n SALMO 145\n Bem-aventurado aquele que espera no Senhor\n\"Sua misericórdia perdura de geração em geração\npara aqueles que o temem\" (Lc 1, 50).\n\n= 1Bendize, minh’alma, ao Senhor! †\n Bendirei ao Senhor toda a vida, *\ncantarei ao meu Deus sem cessar!\n\n– 3Não ponhais vossa fé nos que mandam, *\nnão há homem que possa salvar.\n\n = 4Ao faltar-lhe o respiro ele volta †\npara a terra de onde saiu; *\nnesse dia seus planos perecem.\n= 5É feliz todo homem que busca †\nseu auxílio no Deus de Jacó, *\ne que põe no Senhor a esperança.\n– 6O Senhor fez o céu e a terra, *\nfez o mar e o que neles existe.\n\n– O Senhor é fiel para sempre, *\n faz justiça aos que são oprimidos;\n – ele dá alimento aos famintos, *\né o Senhor quem liberta os cativos.\n\n= 8O Senhor abre os olhos aos cegos, †\no Senhor faz erguer-se o caído, *\no Senhor ama aquele que é justo.\n\n= 9É o Senhor quem protege o estrangeiro, †\nquem ampara a viúva e o órfão, *\nmas confunde os caminhos dos maus.\n\n=10O Senhor reinará para sempre! †\nÓ Sião, o teu Deus reinará *\npara sempre e por todos os séculos!\n\n3ª Ant. Ave, mulher da esperança! De ti nasceu a luz do\n mundo, por ti nos veio o Pão da vida.\nOração sálmica\n\n Ó Senhor, suba até vós o louvor perene dos Servos\nde Santa Maria, porque enviastes o vosso Filho para\nanunciar a Boa Nova aos pobres e proclamar a\nliberdade aos cativos. Reavivai em nós o compromisso\nde socorrer aos mais necessitados com amor fraterno e\nde defender os oprimidos com coragem evangélica. Por\nCristo nosso Senhor. Amém!\n\nIntrodução à leitura\n\nD. Bem-aventurada aquela que acreditou.\nT. Nela encarnou-se o Filho de Deus.\n\nPrimeira leitura\n\n À VIRGEM DO SIM\n\nL. Santa Maria, serva humilde do Senhor, gloriosa Mãe\n de Cristo, salve! Virgem fiel, ventre consagrado ao\n Verbo, ensina-nos a ser dóceis à voz do Espírito, a\n viver na escuta da Palavra, atentos a seus apelos no\n segredo do coração, vigilantes em suas\n manifestações na vida dos irmãos, nos\n acontecimentos da história, nos sofrimentos e nas\n\n alegrias da criação. Virgem da escuta, criatura\n orante, acolhe a súplica dos teus servos!\nResponsório\n\nT. Tu és, ó Maria, a terra prometida, figura do Reino\n que há de vir, * Igreja vivente do Verbo.\nL. Tu a terra sagrada que Cristo ainda geras. Tu a\n custódia vivente da Palavra.\nT. Igreja vivente do Verbo.\nSegunda leitura\n À VIRGEM DO \"MAGNIFICAT\"\nL. Santa Maria, mulher humilde e pobre, bendita do\n Altíssimo, salve! Virgem da esperança, profecia dos\n novos tempos, une ao teu canto as nossas vozes e\n acompanha-nos em nosso caminho, para que\n anunciemos a vinda do Reino e a total libertação dos\n seres humanos. Levando Cristo aos irmãos e irmãs e\n realizando com eles uma intensa comunhão de amor,\n glorificaremos contigo a misericórdia do Senhor e\n cantaremos as alegrias da vida e da salvação.\n Virgem, arca da nova Aliança, primícias da Igreja,\n acolhe as súplicas dos teus servos!\n\nResponsório\n\nT. Tu és a voz do antigo Israel, regozijo do pequeno\n resto, * canto de alegria da virgem Igreja.\nL. Por ti sobe o louvor de todos os remidos, dos pobres\n e humildes que esperam em Deus.\nT. Canto de alegria da virgem Igreja.\n\nTerceira leitura\n À VIRGEM AO PÉ DA CRUZ\nL. Santa Maria, mulher da dor, Mãe dos viventes,\n salve! Nova Eva, Virgem esposa junto à cruz, onde\n se consuma o amor e jorra a vida. Mãe dos\n discípulos, sê tu a imagem-guia em nosso\n compromisso de serviço. Ensina-nos a estar a teu\n lado aos pés das infinitas cruzes da humanidade,\n onde teu Filho continua crucificado; a viver e\n testemunhar o amor cristão, acolhendo todo ser\n humano como irmão; a renunciar ao disfarçado\n egoísmo para seguir a Cristo, única luz da\n humanidade. Virgem da Páscoa, glória do Espírito\n Santo, acolhe a súplica dos teus servos!\n\n SÚPLICA DOS SERVOS DE MARIA\n A NOSSA SENHORA\n Bondade, que nos abres o infinito\n tesouro da graça, Santa Mãe,\n infunde em teus servos a esperança.\n\n Virtude, que com bondade nos socorres\n na incerta e difícil caminhada,\n dá-nos a fidelidade em teu serviço!\n Reaviva em nós\n o antigo e sagrado compromisso\n de servir aos irmãos no amor\n e, com o olhar fixo em ti, seguir a Cristo!\nDespedida\nD. Proteja-nos Santa Maria e benigna nos acompanhe\n pelos caminhos da vida.\nT. Amém!"}, "coroa": "Pelo aporte determinante que os Servos de Maria deram à\nsua composição e pelo amor com que a divulgaram na Igreja, a\nCoroa de Nossa Senhora das Dores (ou a Coroa das Sete Dores)\npode ser considerada uma prática de piedade própria da\nOrdem.\n Não se sabe bem como começou. É muito provável que sua\norigem coincida com o crescimento do culto a Nossa Senhora\ndas Dores do início do século XVII.\n Apresentamos aqui duas fórmulas da Coroa: a primeira\né a tradicional; a segunda é nova, também articulada em \"sete\ndores\": é uma fórmula alternativa, que celebra o inesgotável\nmistério da dor da Virgem Maria a partir da categoria bíblica\nda rejeição, de profundo conteúdo teológico e presente na vida\nde Jesus.\n\n PRIMEIRA FÓRMULA\n\nD. Em nome do Pai, do Filho e do Espírito Santo.\nT. Amém!\n\nD. Nós vos louvamos e vos bendizemos, Senhor.\nT. Porque associastes a Virgem Mãe à obra da\n salvação.\nD. Contemplamos a vossa dor, Santa Maria.\nT. Para seguir-vos no caminho da fé.\n1ª DOR: Maria escuta com fé a profecia de Simeão (Lc\n 2,24-35).\n [Pai nosso e 7 Ave-Marias].\n2ª DOR: Maria foge para o Egito com Jesus e José (Mt\n 2,13-14).\n [Pai nosso e 7 Ave-Marias].\n3ª DOR: Maria procura Jesus, perdido em Jerusalém\n (Lc 2,43-45).\n [Pai nosso e 7 Ave-Marias].\n4ª DOR: Maria encontra-se com Jesus no caminho do\n Calvário (Lc 23, 25-27).\n [Pai nosso e 7 Ave-Marias].\n5ª DOR: Maria ao pé da cruz do Filho (Jo 19,25-27).\n [Pai nosso e 7 Ave-Marias].\n\n6ª DOR: Maria recebe nos braços o corpo de Jesus\n descido da cruz (Mc 15, 42-45).\n [Pai nosso e 7 Ave-Marias].\n\n7ª DOR: Maria deposita o corpo de Jesus no sepulcro, à\n espera da ressurreição (Jo 19, 40-42).\n [Pai nosso e 7 Ave-Marias].\nD. Nós vos louvamos, Santa Maria.\nT. Mãe fiel junto à cruz do Filho.\nD. Bendita sois vós, Rainha dos mártires: associada à\n paixão de Cristo, vos tornastes nossa Mãe.\nT. Sinal de esperança em nosso caminho.\n SEGUNDA FÓRMULA\nD. Em nome do Pai, do Filho e do Espírito Santo.\nT. Amém!\nD. Nós vos louvamos e vos bendizemos, Senhor.\nT. Porque associastes a Virgem Mãe à obra da salvação.\nD. Contemplamos a vossa dor, Santa Maria.\nT. Para seguir-vos no caminho da fé.\n\n1ª DOR: Jesus, Filho de Deus, nasce numa gruta: não\n havia lugar para a mãe na hospedaria (Lc 2,6-7).\n [Pai nosso e 7 Ave-Marias].\n\n2ª DOR: Jesus, Salvador dos homens, sinal de\n contradição (Lc 2,33-35).\n [Pai nosso e 7 Ave-Marias].\n3ª DOR: Jesus, Messias recém-nascido, é perseguido\n por Herodes (Mt 2,13-14).\n [Pai nosso e 7 Ave-Marias].\n\n4ª DOR: Jesus, irmão dos homens, é desprezado por\n seus concidadãos (Lc 4,28-29).\n [Pai nosso e 7 Ave-Marias].\n5ª DOR: Jesus, o Santo de Deus, é preso pelos sumos\n sacerdotes e abandonado pelos discípulos (Mt\n 26, 49-50).\n [Pai nosso e 7 Ave-Marias].\n\n6ª DOR: Jesus, o Justo, morre na cruz (Jo 19,25-27).\n [Pai nosso e 7 Ave-Marias].\n7ª DOR: Jesus, Mestre e Senhor, é perseguido nos seus\n discípulos (At 12, 1-3).\n [Pai nosso e 7 Ave-Marias].\nD. Nós vos louvamos, Santa Maria.\nT. Mãe fiel junto à cruz do Filho.\nD. Bendita sois vós, Rainha dos mártires; associada à\n paixão de Cristo, vos tornastes nossa Mãe.\nT. Sinal de esperança em nosso caminho.\n\n LADAINHA\n DE NOSSA SENHORA DAS DORES\nSenhor, tende piedade de nós! [repete-se]\nCristo, tende piedade de nós!\nSenhor, tende piedade de nós!\nCristo, ouvi-nos.\nCristo, atendei-nos.\n\nDeus Pai que estais no céu, Tende piedade de nós!\nDeus Filho, Redentor do mundo,\nEspírito Santo Paráclito,\nSantíssima Trindade que sois um só Deus,\n\nMãe do crucificado, Rogai por nós!\nMãe de coração traspassado,\nMãe do Cristo Redentor,\nMãe dos discípulos de Jesus,\nMãe dos redimidos,\nMãe dos viventes,\nVirgem obediente,\nVirgem oferente,\nVirgem fiel,\nVirgem do silêncio,\nVirgem do perdão,\nVirgem da espera,\n\nMulher do exílio,\nMulher forte,\nMulher intrépida,\nMulher da dor,\nMulher da nova aliança,\nMulher da esperança.\n\nNova Eva,\nCooperadora do Redentor,\nServa da reconciliação,\nDefesa dos inocentes,\nCoragem dos perseguidos,\nFortaleza dos oprimidos,\nEsperança dos pecadores,\nConsolação dos aflitos,\nRefúgio dos marginalizados.\nConforto dos exilados,\nSustentáculo dos fracos,\nAlívio dos enfermos,\n\nRainha dos mártires,\nGlória da Igreja,\nVirgem da Páscoa,\nCordeiro de Deus, que tirais os pecados do mundo\nT. Perdoai-nos, Senhor!\n\nCordeiro de Deus, que tirais os pecados do mundo\nT. Ouvi-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo\nT. Tende piedade de nós!\n\nOração\n\n Ó Deus, quisestes que a vida da Virgem Maria\nfosse marcada pelo mistério da dor. Humildemente vos\npedimos: concedei-nos trilhar a seu lado o caminho da\nfé e unir nossos sofrimentos à paixão de Cristo, para\nque se tornem momentos de graça e instrumentos de\nsalvação. Por Cristo nosso Senhor. Amém!", "stabat": "Estava a Mãe dolorosa,\njunto da cruz, lacrimosa,\nenquanto o filho pendia.\n\nNa sua alma agoniada\nenterrou-se a dura espada\nde uma antiga profecia.\n\nOh! quão triste e quão aflita,\nentre todas, Mãe bendita,\nque só tinha aquele Filho!\n\nQuanta angústia não sentia\nMãe piedosa, quando via\nas penas do Filho seu!\n\nQuem não chora, vendo isto:\ncontemplando a Mãe do Cristo\nnum suplício tão enorme?\n\nQuem haverá que resista,\nse a Mãe assim se contrista\npadecendo com seu Filho?\nPor culpa de sua gente,\nvia Jesus, inocente,\nentregando o seu espírito.\n\nVê agora o seu amado\npelo Pai abandonado,\nao flagelo submetido.\nFaze, ó Mãe, fonte de amor,\nque eu sinta o espinho da dor,\npara contigo chorar.\n\nFaze arder meu coração\ndo Cristo Deus na paixão,\npara que o possa agradar.\nÓ Santa Mãe, dá-me isto:\ntrazer as chagas do Cristo\ngravadas no coração.\nDo teu Filho, que por mim\nentrega-se a morte assim,\ndivide as penas comigo.\nOh! dá-me, enquanto viver,\ncom Cristo compadecer,\nchorando sempre contigo.\nJunto à cruz eu quero estar,\nquero o meu pranto juntar\nàs lágrimas que derramas.\nVirgem, que às virgens aclara,\nnão sejas comigo avara:\ndá-me contigo chorar.\n\nTraga em mim do Cristo a morte,\nda paixão seja consorte,\nsuas chagas celebrando.\n\nPor elas seja eu rasgado,\npela cruz inebriado,\npelo sangue de teu Filho!\nNo julgamento consegue\nque às chamas não se entregue\nquem por ti é defendido.\nQuando do mundo eu partir,\ndai-me, ó Cristo, conseguir,\npor vossa Mãe, a vitória.\n\nQuando o meu corpo morrer,\npossa a alma merecer\ndo Reino celeste a glória. Amém!", "via_matris": {"intro": "Assim como celebramos a Via Sacra, caminho\npercorrido por Jesus na sua paixão e morte de cruz,\ncelebramos também a Via Matris, isto é, o caminho\nde dor percorrido por Maria, desde a profecia do justo\nSimeão, passando pela fuga para o Egito e a perda de\nJesus no Templo até sua paixão e morte na cruz. Foi\no caminho que ela fez ao lado de Jesus, cooperando\ncom ele na obra de redenção humana.\n Celebramos as dores de Maria não para mover-\nnos de compaixão por ela, pelo que ela sofreu, mas\nantes para encher-nos de coragem e enfrentar como\nela, “de pé”, os sofrimentos desta vida e, ao mesmo\ntempo, para colocar-nos, como ela, aos pés das\ninfinitas cruzes que afligem os homens e mulheres de\nhoje, para levar-lhes conforto e esperança de\nlibertação. Não é, portanto, uma celebração para\nprovocar sentimentalismo pietista, mas sim\ncompaixão e solidariedade com os que sofrem.\n\n14 O presente texto da Via Matris foi composto por frei José M. Milanez, seguindo o\n\n roteiro tradicional, isto é: leitura bíblica, reflexão, invocações e canto.\n\n Desde as origens, os Servos de Maria sempre\ntiveram a Virgem Gloriosa, Mãe da Misericórdia, como\nsua Senhora, Fundadora e Guia. A partir do século XVII\naté meados do século XX, a devoção a Nossa Senhora\ndas Dores passou a ser considerada como o aspecto\npredominante do seu carisma mariano.\n A Via Matris é uma expressão dessa devoção e\nfoi introduzida no Brasil em 1920, quando os\nprimeiros Servos de Maria aqui chegaram. Até a\ndécada de sessenta do século passado era celebrada\ntoda sexta-feira em nossas igrejas. Depois, ficou\nalguns anos esquecida e hoje volta a ser valorizada.\n O presente roteiro da Via Matris segue o\nesquema tradicional, isto é: leitura do evangelho, breve\nreflexão, invocações e canto. Esse exercício de piedade\nevoca as sete principais dores da vida de Maria. Como\na Via Sacra, celebra-se em procissão, passando de uma\nestação para outra. Cada estação representa uma das\nsete dores de Maria.\n A origem dessa prática de piedade remonta ao\nséculo XVIII. Era praticada inicialmente, de maneira\nprivada, nas igrejas dos Servos de Maria da Espanha. É\nde 1842 um documento conservado até hoje, que ensina\ncomo celebrar a Via Matris.\n Esse piedoso exercício é conhecido também\ncomo “Novena perpétua de Nossa Senhora das Dores”\ne teve como seu maior propagador frei Tiago M. Keane\n\n(1901-1975), servita norte-americano que, em 1937,\nintroduziu sua celebração toda sexta-feira na igreja dos\nServos de Maria de Chicago, dedicada à Nossa Senhora\ndas Dores. Daí a devoção expandiu-se rapidamente em\n45 Estados do país e em cerca de 20 países do mundo.\nFrei Tiago escreveu um livreto intitulado “Novena em\nhonra de Nossa Mãe Dolorosa” que alcançou a tiragem\nde seis milhões de exemplares e dezessete edições, e\nfoi traduzido em vinte e dois idiomas15.\n A primeira edição em língua portuguesa foi\npublicada em São Paulo, em 1942. No frontispício do\nlivreto diz-se que foi “extraída de fontes aprovadas e\nadaptada para uso do povo pelo Revdo. Frei Thiago M.\nKeane, O.S.M., e traduzida para o português por frei\nThiago M. Mattioli, O.S.M.”16.\n Os trechos evangélicos são tirados da Bíblia\nSagrada, tradução da CNBB. As orações e a breve\nreflexão que segue à leitura evangélica são uma\nhumilde tentativa do autor para adaptar o conteúdo da\nmensagem e da oração à nossa realidade brasileira. A\nestrofe e o refrão do canto entoado enquanto se passa\n\n Esses dados sobre a Via Matris foram extraídos do Dicionário de Mariologia (dirigido por\n Stefano de Fiores e Salvatore Meo), edição em língua portuguesa, Paulus, São Paulo 1995,\n p. 426-427; cf. também ALESSIO MARIA ROSSI, Manuale di storia dell’Ordine dei Servi\n di Maria, Roma 1956, p. 448-449.\n Novena Perpétua em honra de Nossa Senhora das Dores, trad. frei Thiago M. Mattioli,\n Tipografia do Orfanato Cristóvão Colombo, São Paulo, 1942, 26 p.\n\nde uma estação para outra são do cancioneiro popular\ntradicional.", "stations": [{"title": "1ª Dor — Profecia de Simeão", "text": "D. Nós vos adoramos, Senhor Jesus Cristo e vos\n bendizemos\nT. Porque associastes a Virgem Maria à obra da\n Salvação.\nC. Contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de Lucas (2, 22.25a.34-35)\n Quando se completaram os dias da purificação,\nsegundo a lei de Moisés, levaram o menino a\nJerusalém para apresentá-lo ao Senhor... Vivia em\nJerusalém um homem piedoso e justo, chamado\nSimeão, que esperava a consolação de Israel. Simeão\nos abençoou e disse a Maria, a Mãe: «Este menino será\n\ncausa de queda e de reerguimento para muitos em\nIsrael. Ele será um sinal de contradição. E a ti, uma\nespada traspassará tua alma, e assim serão revelados\nos pensamentos de muitos corações».\n\nReflexão\n L.1 - Jesus, segundo Simeão, haveria de ser um\nsinal de contradição. De fato, para aqueles que o\nrejeitaram e o levaram à cruz, foi motivo de queda e\nde condenação; para aqueles que o aceitaram e\nacreditaram nele, foi motivo de reerguimento e de\nsalvação. Maria guardava todas essas coisas e as\nmeditava no seu coração (Lc 2,19), mas seu olhar\ndeixava transparecer a dor. O poeta contempla o olhar\nde Maria e canta:\n Num sonho todo feito de incerteza,\n de noturna e indizível ansiedade,\n é que eu vi teu olhar de piedade\n e, mais que piedade, de tristeza 17.\n L.2 - Maria conviveu com Jesus em Nazaré e o\nacompanhou na vida pública. Participou de suas\nalegrias e tristezas, mas principalmente do seu\nsofrimento, quando o viu abandonado pelos seus\ndiscípulos, traído por Judas, negado por Pedro,\ncondenado à morte e pregado na cruz. Tudo isso foi\n Trata-se de ANTERO DE QUENTAL (†1891). É a 1ª estrofe do soneto À Virgem Santíssima,\n cheia de graça, Mãe de misericórdia, citado por CLODOVIS M. BOFF, OSM, Nossa Senhora\n das Bem-aventuranças, Edições Paulinas, São Paulo, 1984, p. 20.\n\ncomo uma espada a lhe traspassar a alma. O célebre\nhino Stabat Mater, que descreve a presença de Maria ao\npé da cruz, assim recorda as palavras do justo Simeão:\n«Na sua alma agoniada / enterrou-se a dura espada / de\numa antiga profecia».\n L.3 - Pensemos nas mães dos dias de hoje que\nveem seus filhos levados à morte, vítimas das guerras,\nda fome e de todo tipo de violência. A “espada”\ncontinua a traspassar o coração de muitas mães. O\nhomem e a mulher foram feitos para ter vida e vida em\nabundância e não para morrer, vítimas das “espadas”\nfabricadas pela maldade humana.\nOração\nC. Senhor Deus, nosso Pai, pelas palavras de Simeão,\n predissestes uma vida de sofrimento para a mãe do\n vosso Filho. Suplicantes, vos pedimos: a exemplo da\n Virgem das Dores, cujo coração foi traspassado pela\n espada da dor, saibamos enfrentar os sofrimentos da\n vida presente e ser solidários com as dores dos\n irmãos. Por Cristo nosso Senhor.\nT. Amém!\nInvocações\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, mãe de Deus...\n\n C. Nossa Senhora das Dores.\n T. Rogai por nós!\nCanto\n\n De Simeão as vozes no templo escutais\n cruéis profecias. Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores!"}, {"title": "2ª Dor — Fuga para o Egito", "text": "D. Nós vos adoramos, Senhor Jesus Cristo e vos\n bendizemos\nT. Porque associastes a Virgem Maria à obra da\n Salvação.\n\nC. Contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de São Mateus (2,13-15)\n Depois que os magos se retiraram, o anjo do\nSenhor apareceu em sonho a José e lhe disse: «Levanta-\nte, toma o menino e sua mãe e foge para o Egito! Fica\nlá até que eu te avise, porque Herodes vai procurar o\nmenino para matá-lo». José levantou-se, de noite, com\no menino e a mãe, e partiu para o Egito e lá ficou até a\nmorte de Herodes. Assim se cumpriu o que o Senhor\ntinha dito pelo profeta: “Do Egito chamei o meu filho”.\nReflexão\n L.1 - Herodes dissera aos magos: “Quando\nencontrardes o menino, avisai-me para que também eu\nvá adorá-lo” (Mt 2,8). Mas, conhecendo as más\n\nintenções dele, os magos voltaram para suas terras por\noutro caminho. Herodes então encheu-se de furor,\nporque não podia admitir que houvesse outro rei em\nIsrael. Diante das ameaças de Herodes, José, avisado\npelo anjo do Senhor, teve que fugir com a esposa e a\ncriança.\n L.2 - Abandonar a própria terra e casa, a oficina\nde carpinteiro, parentes e amigos, e rumar para uma\nterra longínqua e desconhecida, percorrendo de Belém\nao delta do Nilo mais de 250 quilômetros, foram atos\nde coragem e de fé de Maria e de José. Mas a ordem de\nDeus era clara: “José, toma o menino e sua mãe e foge\npara o Egito! Fica lá até que eu te avise”. Era preciso\nsalvar o filho a qualquer custo.\n L.3 - Quantos são hoje os que vivem exilados ou\nmigrando de um lugar para outro, sempre fugindo dos\nHerodes atuais, que se chamam perseguição, racismo,\nconflitos étnicos, fome, desemprego, falta de moradia,\nde assistência médica e de educação, e sempre\nbuscando, no desconhecido, melhores condições de\nvida. Milhões são os prófugos, exilados e migrantes\nque vagueiam pelo mundo, longe de sua terra, dos\nparentes e amigos, erradicados de sua cultura. A\nhistória se repete. É o desterro forçado da Família de\nNazaré que se prolonga na história da humanidade.\n\nOração\nC. Senhor Deus, nosso Pai, fizestes da Virgem Maria a\n mulher forte que conheceu a pobreza e o sofrimento,\n a fuga e o exílio. Suplicantes, vos pedimos: a exemplo\n da Virgem das Dores, saibamos lutar para defender a\n vida e os direitos da pessoa humana contra as\n injustiças e a perseguição dos prepotentes. Por Cristo\n nosso Senhor.\nT. Amém!\nInvocações\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, mãe de Deus...\n C. Nossa Senhora das Dores\n T. Rogai por nós!\n\nCanto\n Manda o céu um anjo dizer que fujais\n do bárbaro Herodes, Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores!"}, {"title": "3ª Dor — Jesus perdido em Jerusalém", "text": "C. Nós vos louvamos, Senhor Jesus Cristo e vos\n bendizemos.\nT. Porque associastes a Virgem Maria à obra da\n salvação.\n\nC. Contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\n\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de Lucas (2, 41-49)\n\n Todos os anos, os pais de Jesus iam a Jerusalém\npara a festa da Páscoa. Quando o menino completou\ndoze anos, eles foram para a festa, como de costume.\nTerminados os dias da festa, enquanto voltavam, Jesus\nficou em Jerusalém, sem que seus pais percebessem.\nPensando que se encontrasse na caravana, caminharam\num dia inteiro. Começaram então a procurá-lo entre os\nparentes e conhecidos. Mas não o encontrando,\nvoltaram a Jerusalém à sua procura. Depois de três dias,\no encontraram no templo, sentado entre os mestres,\nouvindo-os e fazendo-lhes perguntas.\n\nReflexão\n\n L.1 - Aos doze anos, todo menino judeu era\nlevado ao templo e entregue aos mestres da lei para que\nlhe ensinassem a Lei do Senhor, que se encontra no\nPentateuco, os primeiros cinco livros da Bíblia. Assim\nfizeram seus pais com Jesus. Só que os pais, quando já\nestavam no caminho de volta para Nazaré, se dão conta\nque o Menino não está na caravana.\n L.2 - Podemos imaginar a aflição de Maria e José\nque o procuram por toda parte, não o encontram e têm\nque voltar a Jerusalém. E já tinham feito o caminho de\num dia. É bom saber que Nazaré dista de Jerusalém\nmais de cem quilômetros. À angústia une-se o cansaço\nda viagem. Além do mais, Maria e José ainda\nguardavam na memória as ameaças de Herodes e a fuga\npara o Egito.\n L.3 - É dramática hoje a situação de tantas\ncrianças perdidas, que vagueiam pelas ruas e praças das\ncidades, fugidas de casa ou roubadas às suas famílias,\nmatriculadas pelo destino na escola das drogas, da\nprostituição e da violência, alvo elas próprias de todo\ntipo de violência. São as “crianças de rua” que vemos\npor aí: maltrapilhas, sujas, drogadas, dormindo na\ncalçada, pedindo esmola, assaltando os passantes.\nVivendo assim, o que vão aprender para a vida essas\ncrianças? Como poderão crescer sadias? Quando\n\naparecerá alguém que vá procurá-las e resgatá-las dessa\nsituação?\nOração\n\nC. Senhor Deus, nosso Pai, por três dias, Maria e José\n procuraram, aflitos, o filho Jesus. Suplicantes, vos\n pedimos: amparados pela Virgem das Dores,\n busquemos na penitência e na conversão o\n reencontro com o vosso Filho, e sejamos solidários\n com tantas crianças, que vagueiam pelas ruas e\n praças vítimas da injustiça social, da desagregação\n familiar e da violência. Por Cristo nosso Senhor.\nT. Amém!\nInvocações\n\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, mãe de Deus...\n C. Nossa Senhora das Dores\n T. Rogai por nós!\nCanto\n Voltando do templo, Jesus não achais.\n Que susto sofrestes! Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores!"}, {"title": "4ª Dor — Encontro no caminho do Calvário", "text": "C. Nós vos louvamos,\n Senhor Jesus Cristo e vos bendizemos.\nT. Porque associastes a Virgem Maria à obra da\n salvação.\nC. Nós contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de Lucas (23,26-28)\n Enquanto levavam Jesus, tomaram um certo\nSimão de Cirene, que voltava do campo, e mandaram-\nno carregar a cruz atrás de Jesus. Seguia-o uma grande\nmultidão do povo, bem como de mulheres que batiam\nno peito e choravam por ele. Jesus, porém, voltou-se\npara elas e disse: “Mulheres de Jerusalém, não choreis\npor mim! Chora por vós mesmas e por vossos filhos!”\n\n L.1 – O Evangelho não diz explicitamente se no\nmeio da “grande multidão que o seguia” ou das\n“mulheres que batiam no peito” estava também a mãe\nde Jesus, mas certamente ela devia estar. De fato, logo\ndepois o Evangelho de João diz que ela estava junto à\ncruz do Filho agonizante, ao lado do discípulo amado e\nde outras mulheres.\n\n L.2 - É o encontro doloroso da mãe aflita com o\nfilho condenado à morte. Ao sofrimento físico de Jesus\njunta-se o sofrimento daquela que vê o filho, que passara\na vinda pregando e fazendo o bem, ser incompreendido,\ninjustiçado, caluniado e condenado à morte de cruz.\nJesus e Maria unem-se na dor para realizar a obra de\nredenção da humanidade.\n L.3 - Quem nunca viu, nos dias de hoje, mães\nperderem seus filhos, vítimas da violência e da maldade\nhumana? Referindo-se a Maria, assim canta o poeta18:\n Tu és, ó mãe, toda mãe que hoje ama;\n tu és, ó mãe, toda a mãe que hoje chora\n seu filho morto, seu filho traído,\n mães aos milhares, mães amortalhadas!\n Filhos que sempre se estão a matar,\n Trata-se de frei DAVID M. TUROLDO, escritor e poeta da Ordem dos Servos de Maria, que\n compôs os hinos dos Ofícios Próprios OSM. Esses versos são do hino do Ofício das Leituras\n da festa da “Bem-aventurada Virgem Maria ao pé da Cruz”.\n\n Filhos vendidos, traídos, sem número,\n filhos feridos e em cruzes pregados:\n ímpia bandeira de um ímpio poder.\nOração\nC. Senhor Deus, nosso Pai, no caminho do Calvário,\n vosso filho Jesus e Maria sua mãe se encontram.\n Suplicantes, vos pedimos: a exemplo da Virgem das\n Dores, saibamos ir ao encontro dos que sofrem,\n compreendendo, compartilhando e aliviando suas\n dores. Por Cristo nosso Senhor.\nT. Amém!\n\nInvocações\n\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, mãe de Deus...\n C. Nossa Senhora das Dores\n T. Rogai por nós!\nCanto\n\n Que dor indizível quando o encontrais\n com a cruz às costas. Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores!"}, {"title": "5ª Dor — Maria ao pé da cruz", "text": "C. Nós vos louvamos, Senhor Jesus Cristo e vos\n bendizemos.\nT. Porque associastes a Virgem Maria à obra da\n salvação.\nC. Nós contemplamos vossas dores, ó Mãe de\n Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de João (19,25-27)\n Junto à cruz de Jesus estavam de pé sua mãe e a\nirmã de sua mãe, Maria de Cléofas, e Maria Madalena.\nJesus, ao ver sua mãe, ao lado dela, o discípulo que ele\namava, disse à mãe: “Mulher, eis o teu filho!” Depois\ndisse ao discípulo: “Eis a tua mãe!” A partir daquela\nhora, o discípulo a acolheu junto de sim\n\nReflexão\n\n L.1 - É a cena clássica do Calvário, descrita por\nJoão e tão comentada pelos santos Padres da Igreja, que\na iconografia ilustrou com as mais variadas formas e\nestilos e que o poeta canta dizendo19: Sim, no\nCalvário, ó Mãe, tu choraste,\n ao pé da cruz, traspassada de dor:\n como pudeste sofrer tanto assim,\n sem sucumbir, nem fugir, nem gritar?\n L.2 - Eram poucos ao pé da Cruz. Dos doze\ndiscípulos, apenas um. De todos os que haviam sido\nbeneficiados pelos milagres e curas de Jesus, ninguém.\nMas lá estava Maria, a mãe, de pé, e outras mulheres.\nColocar-se com Maria aos pés das infinitas cruzes que\nafligem os homens e as mulheres do nosso tempo é\nmissão prioritária do cristão. “Tive fome e me destes de\ncomer; tive sede e me destes de beber; fui peregrino e\nme acolhestes; estive nu e me vestistes, enfermo e me\nvisitastes, preso e viestes ver-me...” (Mt 25,35-36)\n L.3 - Basta olhar ao nosso redor, abrir um jornal\nou ver um noticiário de TV para constatar quantas são\nas cruzes que afligem a humanidade de hoje. “Toda\ncriação espera ser libertada da escravidão”, exclama São\nPaulo (Rm 8,21). Que fazer? É nosso dever de cristãos e\nde Servos de Maria colocar-nos aos pés dessas infinitas\n Do Hino das Vésperas da festa da B. Virgem Maria ao pé da Cruz.\n\ncruzes, onde o Filho do Homem continua sendo\ncrucificado nos irmãos e irmãs, para levar-lhes conforto\ne esperança de libertação. Maria, a mãe da misericórdia\ne da compaixão, nos dá o exemplo. Seja ela a nossa\nimagem-guia.\nOração\nC. Senhor Deus, nosso Pai, que ao pé da cruz\n associastes a Virgem Maria à paixão e morte do\n vosso Filho, fazendo-a corredentora da humanidade.\n Suplicantes, vos pedimos: a exemplo da Virgem das\n Dores, saibamos colocar-nos a seu lado aos pés das\n cruzes da humanidade onde vosso Filho continua\n crucificado em nossos irmãos e irmãs, para levar-\n lhes conforto esperança de libertação. Por Cristo\n nosso Senhor.\nT. Amém!\nInvocações\n C. Ave Maria, cheia de graça...\n T. Santa Maria, Mãe de Deus...\n C. Nossa Senhora das Dores,\n T. Rogai por nós!\nCanto\n A dor ainda cresce quando contemplais\n Jesus expirando. Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores!"}, {"title": "6ª Dor — Jesus depositado nos braços de Maria", "text": "C. Nós vos louvamos, Senhor Jesus Cristo e vos\n bendizemos.\nT. Porque associastes a Virgem Maria à obra da\n salvação.\nC. Nós contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de Marcos (15,43-46a)\n José de Arimateia, membro respeitável do\nSinédrio, que também esperava o reino de Deus, cheio\nde coragem foi a Pilatos pedir o corpo de Jesus.\n Pilatos ficou admirado quando soube que Jesus\nestava morto. Chamou o centurião e perguntou se tinha\nmorrido havia muito tempo. Informado pelo centurião,\n\nPilatos entregou o corpo a José. Ele comprou um lençol\nde linho, desceu Jesus da cruz e envolveu-o no lençol.\nReflexão\n L.1 – Eis a “Pietà” (a Piedade), obra-prima de\nMichelangelo, venerada na basílica de São Pedro, no\nVaticano, e reproduzida em milhares de cópias\nespalhadas pelo mundo inteiro. Maria, sentada,\naconchega ao colo seu filho morto. A perfeição dos\ntraços das imagens marmóreas de Jesus e de Maria e a\ndor reproduzida com solenidade e perfeição no rosto da\nmãe despertam piedade e compaixão.\n L.2 - Diante desse quadro, canta o poeta 20:\nPouco mais tarde da cruz o tiraram,\ne o depuseram, ó Mãe, em teu colo.\nNão parecias gerá-lo de novo?\ne qual criança de peito aleitá-lo?\n Eras o colo de todas as mães.\n Vendo-te assim, quem não há de chorar?\n Era uma cena jamais antes vista!\n És a Piedade que abraça quem sofre!\n L.3 - Abraçar a dor do irmão, abraçar a causa dos\npobres, dos excluídos, dos doentes, dos angustiados e\ndeprimidos, não é para os fracos. É para os fortes. Para\naqueles que, como Maria, sabem permanecer de pé junto\nà cruz e não se abalam nem desanimam diante do\nsofrimento. Para aqueles que alicerçam sua vida em Deus\ne na sua Palavra. Para aqueles que, diante da morte,\n Do hino das II Vésperas da solenidade de Nossa Senhora das Dores, 15 de setembro.\n\nacreditam na ressurreição, e por isso lutam para renovar\no mundo e se empenham com obras de caridade e de\nmisericórdia, a exemplo do bom samaritano. Sim, porque\nnão existe fé sem obras. “Mostra-me tua fé sem as obras\nque eu, por minhas obras, te mostrarei a fé“, diz São\nTiago.\nOração\nC. Senhor Deus, nosso Pai, estando “tudo consumado”,\n o corpo do vosso filho foi descido da cruz e entregue\n nos braços de sua mãe. Suplicantes, vos pedimos: a\n exemplo da Virgem das Dores, tenhamos os braços\n sempre abertos para acolher os excluídos da\n sociedade, escutar seus clamores e solidarizar-nos\n com eles na luta pela vida. Por Cristo nosso Senhor.\nT. Amém!\n Invocações\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, Mãe de Deus...\n C. Nossa Senhora das Dores\n T. Rogai por nós!\n Canto\n No vosso regaço seu corpo abrigais,\n com ele abraçada, bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores."}, {"title": "7ª Dor — Sepultamento de Jesus", "text": "C. Nós vos louvamos, Senhor Jesus Cristo e vos\n bendizemos.\nT. Porque associastes a Virgem Maria à obra da\n salvação.\nC. Nós contemplamos vossas dores, ó Mãe de Deus!\nT. Queremos seguir-vos no caminho da fé.\nC. Santa Maria, Mãe de Deus!\nT. Rogai por nós, pecadores.\nEvangelho de João (19,40-42)\n Eles pegaram então o corpo de Jesus e o\nenvolveram, com perfumes, em faixas de linho, do\nmodo como os judeus costumam sepultar. No lugar\nonde Jesus foi crucificado, havia um jardim e, no\njardim, um túmulo novo, onde ninguém tinha sido\nainda sepultado. Por ser dia de preparação para os\n\njudeus, e como o túmulo estava perto, foi lá que eles\ncolocaram Jesus.\n\n Reflexão\n\n L.1 - Foi um enterro de pobre, feito às pressas no\nfinal da tarde, e poucos o acompanharam, como reza a\nLiturgia:\n Para o sepulcro o levam amigos,\n não mais que sete, segundo João:\n foi o enterro mais pobre do mundo,\n ouve-se apenas a pedra a rolar... 21\nTudo parece ter chegado ao fim. A Mãe, João e os\npoucos amigos e amigas, depois que o túmulo foi\nfechado com a pedra, voltam para casa. A desolação é\ntotal. A dor da mãe alcança seu nível mais profundo:\nagora sem marido e sem filho. Estava só! É Nossa\nSenhora da Soledade.\n L.2 - Mas Ela não perde a esperança: seu Filho\nressuscitará, como ele mesmo disse. Ela o deposita no\nsepulcro, sim, mas espera sua ressurreição. Ademais,\nEla toma consciência do alcance das palavras de Jesus:\n«Eis aí o teu filho!» E assume a sua função de mãe de\ntodos os homens e mulheres. No Natal, tornara-se mãe\nde Jesus. Agora, no Calvário, mãe de todos os seres\n\n Hino das II Vésperas do Ofício da Solenidade de Nossa Senhora das Dores.\n\nhumanos. E, mais tarde, em Pentecostes, mãe da Igreja.\nMaria alcança a plenitude da maternidade.\n L.3 - Esta a fé que deve acompanhar-nos quando\nsepultamos uma pessoa querida: o corpo é posto debaixo\nda terra, mas sua “vida” continua. Uma vez gerados no\nventre materno, nossa “vida” dura para sempre: alguns\nanos, envolvida no corpo humano, depois, revestida de\num “corpo incorruptível”. Como será isso? Deus sabe\ne isso nos basta.\nOração\nC. Senhor Deus, nosso Pai, junto com alguns irmãos e\n irmãs, a Virgem Mãe, aflita, acompanhou seu filho à\n sepultura. Suplicantes, vos pedimos: a exemplo da\n Virgem das Dores, saibamos caminhar lado a lado\n com aqueles que sofrem, para criarmos com eles\n uma aliança de amor, que os ajude a superar o medo\n da morte com a esperança da ressurreição. Por Cristo\n nosso Senhor.\nT. Amém!\nInvocações\n C. Ave, Maria, cheia de graça...\n T. Santa Maria, mãe de Deus...\n C. Nossa Senhora das Dores\n T. Rogai por nós!\n\nCanto\n\n Sem filho, e tal filho! Então suportais\n cruel soledade. Bendita sejais!\n Bendita sejais, Senhora das Dores,\n ouvi nossos rogos, mãe dos pecadores.\n\n[Termina-se a “Via Matris”, recitando a ladainha de\nNossa Senhora das Dores (cf. p.), seguida do oremos\n(cf. p. ) e da bênção final]."}]}, "ladainhas": [{"title": "Ladainha dos Servos de Maria", "text": "Senhor, tende piedade de nós. [repete-se]\nCristo, tende piedade de nós.\nSenhor, tende piedade de nós.\nCristo, ouvi-nos.\nCristo, atendei-nos.\n\nDeus Pai do céu, Tende piedade de nós!\nDeus Filho, redentor do mundo,\nEspírito Santo Paráclito,\nSantíssima Trindade que sois um só Deus,\n\nAve Maria, Virgem morada do Espírito, Rogai por nós!\nAve Maria, Virgem Mãe,\nAve Maria, Virgem fiel,\nAve Maria, Virgem sábia,\nAve Maria, Virgem prudente,\nAve Maria, Virgem orante,\nAve Maria, Mãe de Deus,\nAve Maria, Mãe de Cristo,\nAve Maria, Mãe do Salvador,\nAve Maria, Mãe do Homem novo,\nAve Maria, Mãe da graça,\nAve Maria, Mãe da misericórdia,\nAve Maria, sede da sabedoria,\nAve Maria, templo de santidade,\nAve Maria, arca da aliança,\nAve Maria, estrela do mar,\nAve Maria, escada do céu,\nAve Maria, porta do paraíso,\nAve Maria, conforto dos pobres,\nAve Maria, refúgio dos marginalizados,\nAve Maria, saúde dos enfermos,\nAve Maria, guia dos peregrinos,\nAve Maria, esperança dos pecadores,\nAve Maria, alegria dos teus servos,\nAve Maria, mestra da santidade,\nAve Maria, mestra da humildade,\nAve Maria, mestra da obediência,\nAve Maria, mestra da fortaleza,\nAve Maria, mestra da contemplação,\nAve Maria, mestra do serviço,\nAve Maria, fonte de vida,\nAve Maria, fonte de luz,\nAve Maria, fonte de beleza,\nAve Maria, fonte de alegria,\nAve Maria, fonte de perdão,\nAve Maria, fonte de comunhão,\nAve Maria, rainha dos humildes,\nAve Maria, rainha dos mansos,\nAve Maria, rainha dos misericordiosos,\nAve Maria, rainha dos puros de coração,\nAve Maria, rainha dos construtores da paz,\nAve Maria, rainha dos teus servos,\n\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Perdoai-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Ouvi-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Tende piedade de nós!\n\nOração\n\nÓ Deus, amigo dos homens, fiel à aliança e às promessas, que no anúncio a Maria realizastes a espera da humanidade, escutai a nossa oração: pela disponibilidade que encontrastes na Virgem Maria, filha de Sião e nossa irmã, fazei que nós, vossos servos, sejamos sempre dóceis à Palavra e abertos ao vosso Espírito. Por Cristo nosso Senhor. Amém!"}, {"title": "Ladainha de Santa Maria da Esperança", "text": "Senhor, tende piedade de nós. [repete-se]\nCristo, tende piedade de nós.\nSenhor, tende piedade de nós.\nCristo, ouvi-nos.\nCristo, atendei-nos.\n\nDeus Pai do céu, Tende piedade de nós!\nDeus Filho, redentor do mundo,\nEspírito Santo Paráclito,\nSantíssima Trindade que sois um só Deus,\n\nSanta Maria da esperança, Rogai por nós!\nSanta Maria do caminho,\nSanta Maria da luz,\nPlenitude de Israel,\nAurora do mundo novo,\nFonte da alegria messiânica,\nMãe de Deus,\nMãe do Messias libertador,\nMãe dos redimidos,\nMãe de todos os povos,\n\nDiscípula de Cristo,\nTestemunha de Cristo,\nIrmã dos homens,\nInício da Igreja,\nMãe da Igreja,\nModelo da Igreja,\nImagem da Igreja,\nServa do Senhor,\nServa da Palavra,\nServa do Reino,\nVirgem do silêncio,\nVirgem da escuta,\nVirgem do canto,\nVirgem da contemplação,\nMaria, dignidade da mulher,\nMaria, grandeza da mulher,\nMaria, destino da mulher,\nMulher bendita entre as mulheres,\nMulher fiel ao compromisso,\nMulher fiel no seguimento,\nMulher fiel ao pé da cruz,\n\nEstrela da evangelização,\nEducadora da fé,\nMestra da vida,\nPresença luminosa,\nPresença orante,\nPresença acolhedora,\nPresença operante,\nEsperança dos pobres,\nConfiança dos homens,\nSustentáculo da evangelização,\nAlívio dos oprimidos,\nDefesa dos inocentes,\nFortaleza dos perseguidos,\nConforto dos exilados,\nVoz de comunhão,\nVoz dos pobres,\nVoz do Espírito,\n\nSinal do rosto materno de Deus,\nSinal da presença do Pai,\nSinal da misericórdia do Filho,\nSinal da fecundidade do Espírito,\n\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Perdoai-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Ouvi-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Tende piedade de nós!\n\nOração\n\nPai Santo, que no caminho da Igreja, peregrina sobre a terra, colocastes como sinal luminoso a bem-aventurada Virgem Maria: por sua intercessão, sustentai nossa fé e reacendei nossa esperança, para que nenhum obstáculo nos desvie do caminho que leva à salvação. Por Cristo nosso Senhor. Amém!"}, {"title": "Ladainha de Puebla", "text": "Senhor, tende piedade de nós. [repete-se]\nCristo, tende piedade de nós.\nSenhor, tende piedade de nós.\nCristo, ouvi-nos.\nCristo, atendei-nos.\n\nDeus Pai do céu, Tende piedade de nós!\nDeus Filho, redentor do mundo,\nEspírito Santo Paráclito,\nSantíssima Trindade que sois um só Deus,\n\nDiscípula perfeita do Senhor, Libertai vosso povo.\nModelo do cristão,\nRealização mais alta do Evangelho,\nFace materna de Deus,\nRosto do homem novo,\nCoração tão grande quanto o mundo,\nMulher forte do povo,\nMulher pobre e sofredora,\nMulher perseguida e exilada,\nAnunciadora da justiça dos oprimidos,\nInspiradora da opção pelos pobres,\nMulher que dignifica a mulher,\nSinal do nosso corpo glorificado,\nSinal da criação redimida,\nSinal do homem todo salvo,\nIntercessora de todos os povos,\nDespertadora da fé no Cristo,\nEncarnação viva do evangelho,\nFiel companheira do Senhor,\nProtagonista, com Cristo, da história,\nGuarda do destino da América Latina,\nMãe educadora da fé,\nPedagoga do evangelho,\nEstrela da evangelização,\n\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Perdoai-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Ouvi-nos, Senhor!\nCordeiro de Deus, que tirais os pecados do mundo,\nT. Tende piedade de nós!"}], "sabado": {"intro": "TEMPO COMUM\n\"Falta ainda acenar à possibilidade de uma comemoração litúrgica frequente da Virgem \nSantíssima, mediante o recurso à memória de Santa Maria no sábado: memória antiga e discreta, \nque a flexibilidade do calendário atual e a multiplicidade de formulários do Missal tornam \nextremamente fácil e variada\" (Marialis Cultus, 9).\nNos sábados do Tempo Comum, não havendo outra memória obrigatória, celebra-se a memória de Santa \nMaria, usando-se o formulário da Liturgia das Horas do rito romano ou o Ofício próprio da Ordem.", "form1": "Invitatório\nAnt. Vinde, adoremos o Cristo Jesus, que nos deu Maria como Mãe e Senhora.\nSalmo invitatório como no Ordinário, p. 35.\nOfício das Leituras\nHINO\nVamos servir nós também, ó irmãos,\nseguindo atentos o exemplo da Mãe:\nfechar-se em casa não pode sozinho\nquem Cristo traz dentro em seu coração.\nReis e princesas seus tronos já deixem\ne saiam todos dos grandes palácios;\nos sacerdotes, os templos deixando,\nlevem a graça ao encontro dos homens.\nE todos cantem o mesmo seu canto,\ndigam aos pobres: Já veio o Messias,\nem nossa carne mortal veio e vem:\neles serão do seu reino os herdeiros.\nA Igreja acolham os que são os últimos\ncom as palavras que disse Isabel,\ne os filhos inda no ventre das mães\nvibrem alegres por terem nascido.\nA ti, Trindade, mistério supremo,\nnós te louvamos porque nos doaste\na nova aurora que o dia anuncia:\nCristo, que toda a criação glorifica.\nAntífonas, salmos, versículo e primeira leitura com o respectivo responsório, do sábado da semana corrente.\nSEGUNDA LEITURA\nDa alocução de Paulo VI aos participantes do Capítulo Geral da Ordem dos Servos de Maria\n(Roma, 12 de outubro de 1974)\nGloriai-vos de ser Servos da Mãe de Deus\nCom a mente e o espírito, tende sempre diante de vós o exemplo eminente e arrebatador da\nVirgem Maria, à qual a vossa Ordem está consagrada por um título especial. [Leitura completa\ndisponível no ofício impresso da Ordem.]\nRESPONSÓRIO cf. Lc 1,38; Mt 6,10\nR. Maria respondeu ao anjo: Eis aqui a serva do Senhor. * Deus faça em mim segundo a tua palavra.\nV. Quando orardes, dizei: Seja feita a vossa vontade assim na terra como no céu.\nR. Deus faça em mim segundo a tua palavra.\nLeitura alternativa\nDa \"Legenda sobre a origem da Ordem dos Servos da bem-aventurada Virgem Maria\"\nConsagram-se de modo especial ao serviço de Nossa Senhora\nA bem-aventurada Virgem Maria, Mãe de nosso Senhor Jesus Cristo, é o refúgio universal de\ntodos os pecadores, mãe universal de todos os justos e é reconhecida como Senhora comum de\ntodos os que servem a Cristo. [Leitura completa disponível no ofício impresso da Ordem.]\nRESPONSÓRIO\nR. Unidos pelo vínculo da caridade e da fé, vivamos em comunhão fraterna sob a proteção de Nossa\nSenhora, * para servir a Deus e aos irmãos.\nV. Consagrando nossas vidas à bem-aventurada Virgem, ela será para nós refúgio especial, mãe\nsingular e Senhora nossa.\nR. Para servir a Deus e aos irmãos.\nOração\nÓ Deus misericordioso, atendei a oração dos vossos Servos reunidos para celebrar a memória da\nSanta Virgem Maria. Por sua maternal intercessão, livrai-nos de todos os perigos que nos ameaçam\nneste mundo. Por nosso Senhor.\nOu:\nSenhor, vós quisestes que a Santa Virgem Maria, vossa Serva, fosse mãe de Cristo e a ele estivesse\nsempre unida. Concedei-nos que, inspirados na Senhora nossa, testemunhemos o evangelho,\ncolocando-nos a serviço da salvação dos irmãos. Por nosso Senhor.\nLaudes\nHINO\nCom este nome veneram-te muitos:\nServos chamados de Santa Maria,\nirmãos eleitos p'ra amar e doar-se,\nqual povo nobre dos tempos de outrora.\nPor isso, a vida queremos cantar\nda que se fez do Senhor Serva humilde,\ndo Filho amado descido do céu,\npara ser servo de todos os homens.\nEste é o preceito do Filho divino:\n\"Quem quer seguir-me comece a servir\",\ne aquele que ama a amar recomece,\naté verter o seu sangue primeiro.\nA vida inteira sua Mãe o seguiu\naté a cruz, fielmente e em silêncio:\nassim co'os pobres ao mundo o entregou,\nco'eles cumprindo o comum sacerdócio.\nNão outra Igreja será verdadeira\ne fora disto não há sacramento:\nMaria Virgem é a Igreja primeira,\nela que disse: \"Eis aqui vossa serva\".\nAntífonas e salmos do sábado da semana corrente.\nLEITURA BREVE Jt 13,14a.18ab.19\nJudite disse: Louvai a Deus, louvai-o! Louvai a Deus que não afastou a sua misericórdia da casa de\nIsrael. Ozias, príncipe do povo de Israel, disse-lhe: Bendita sejas, filha, pelo Deus Altíssimo, mais\nque todas as mulheres da terra, e bendito seja o Senhor Deus, Criador do céu e da terra.\nRESPONSÓRIO BREVE Lc 1,42.45\nR. Bendita és tu entre as mulheres, * e bendito é o fruto do teu ventre!\nV. Feliz és tu, ó Maria, que acreditaste no cumprimento das palavras do Senhor.\nR. E bendito é o fruto do teu ventre!\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Bendita és tu entre as mulheres e bendito é o fruto do teu ventre!\nCântico evangélico\nAnt. Salve, Santa Maria, glória de Jesus Cristo! Vossos servos vos invocam, ó Virgem bendita!\nOu: Salve, fonte de clemência, Rainha do céu! Vosso olhar misericordioso a nós volvei.\nPRECES\nRenovados pela luz matinal, confiemos a Deus Pai, fonte do eterno esplendor, todas as esperanças e\npropósitos deste novo dia. Digamos juntos:\nR. Senhor, fazei-nos testemunhas da ressurreição de Cristo.\nPor intercessão de Santa Maria, vossa Serva, fazei que vos amemos de coração sincero,\n- e aceitemos vossa vontade com amor filial.\nPor intercessão de Santa Maria, Senhora nossa, inspirai-nos as palavras, sustentai o nosso trabalho e\nguiai-nos em tudo o que fizermos neste dia,\n- para que, gratos pelo dom da vida, façamos dela um instrumento de generoso serviço aos irmãos.\nPor intercessão de Santa Maria, sede da Sabedoria, derramai a luz da vossa verdade,\n- para que compreendamos sempre melhor os valores humanos e sagrados representados pela\nVirgem Maria.\nPor intercessão de Santa Maria, morada do Espírito Santo, fazei de nós templos do divino Paráclito,\n- para que a retidão da nossa conduta suba até vós como sacrifício de agradável odor.\nPai Nosso...\nOração\nO Deus misericordioso, atendei a oração dos vossos Servos reunidos para celebrar a memória da\nSanta Virgem Maria. Por sua maternal intercessão, livrai-nos de todos os perigos que nos ameaçam\nneste mundo. Por nosso Senhor.\nOu:\nSenhor, vós quisestes que a Santa Virgem Maria, vossa Serva, fosse mãe de Cristo e a ele estivesse\nsempre unida. Concedei-nos que, inspirados na Senhora nossa, testemunhemos o evangelho,\ncolocando-nos a serviço da salvação dos irmãos. Por nosso Senhor.", "form1Title": "SANTA MARIA DOS SEUS SERVOS", "form2": "Invitatório\nAnt. Vinde, adoremos a Cristo! Ele salvou a humanidade unindo a si Maria e a Igreja.\nSalmo invitatório como no Ordinário, p. 35.\nOfício das Leituras\nHINO\nVenham, irmãos, procurá-lo conosco:\nhá muitos séculos nós o perdemos,\njá não choramos assim como a Mãe,\nque por três dias ansiosa o procura!\nSem Jesus Cristo não temos mais Deus\ne nem irmãos uns dos outros nós somos:\na nossa casa tornou-se um deserto,\n\"Toda Sião é um funesto deserto!\"\nA própria Mãe pela mão nos conduza,\nricos ou pobres, ateus ou fiéis:\nMãe sendo ela de todos os crentes,\nmostre-nos onde poder encontrá-lo.\nA ti, Trindade, mistério supremo,\nnós te louvamos porque nos doaste\na nova aurora que o dia anuncia:\nCristo, que toda a criação glorifica.\nAntífonas, salmos, versículo e primeira leitura com respectivo responsório, do sábado da semana corrente.\nSEGUNDA LEITURA\nDa Constituição dogmática \"Lúmen Gentium\" do Concílio Vaticano II sobre a Igreja (n° 63-65)\nA Virgem Maria precedeu à Igreja qual seu protótipo\nEm virtude da graça da divina maternidade e da missão pela qual ela está unida com seu Filho\nRedentor, a bem-aventurada Virgem está também intimamente relacionada com a Igreja. Já Santo\nAmbrósio ensinava que a Mãe de Deus é o tipo da Igreja na ordem da fé, da caridade e da perfeita\nunião com Cristo. [Leitura completa disponível no ofício impresso da Ordem.]\nRESPONSÓRIO\nR. O Filho unigénito do Pai fez-se Filho da Virgem e Senhor de sua Mãe. * A cabeça foi gerada por\nMaria e os membros são frutos da Igreja.\nV. Cristo, em Maria se torna pequeno, e na Igreja se torna admiravelmente grande.\nR. A cabeça foi gerada por Maria e os membros são frutos da Igreja.\nLeitura alternativa\nDos \"Sermões\" de Santo Agostinho, bispo\nA Igreja: mãe santa e honrada, semelhante a Maria\nMeus irmãos, prestai bem atenção, rogo-vos, prestai bem atenção ao que disse Jesus, apontando\npara os discípulos: \"Aqui estão a minha mãe e os meus irmãos, porque aquele que fizer a vontade de\nmeu Pai que está nos céus, esse é meu irmão, irmã e mãe\" (cf. Mc 3,34-35; Mt 12,49-50).\n[Leitura completa disponível no ofício impresso da Ordem.]\nRESPONSÓRIO\nR. Santa Maria, Virgem e Mãe, no coração e no ventre gerais para o mundo o Filho do Pai; * à\nsombra do Espírito Santo, confiais plenamente na palavra de Deus.\nV. Feliz vós também, santa Igreja, virgem e mãe: cumprindo fielmente a vontade do Pai, na fonte\nbatismal gerais muitos filhos de Deus para a vida eterna.\nR. À sombra do Espírito Santo, confiais plenamente na palavra de Deus.\nOração\nO Deus, que sois guia do povo eleito, quisestes que a Santa Virgem, Mãe de Cristo, cabeça da\nIgreja, fosse também mãe espiritual dos cristãos; por sua maternal intercessão, concedei que todos\nos povos se tornem vossa Igreja. Por nosso Senhor.\nLaudes\nHINO\n\"Ventre feliz o de quem te gerou!\",\nem meio ao povo gritou a mulher,\ntoda inflamada com Suas palavras:\nporém só tu conhecias as coisas!\nDize, ó Mãe, o que foi que provaste,\nem Nazaré quando o Livro ele leu:\n\"Em mim repousa o Espírito Santo,\npalavra que hoje se cumpre!\" - dizia.\nContigo, ó Mãe, nós queremos segui-lo\npelos caminhos cantando a Deus Pai:\ntu a primeira que creste no Filho\ne nós a Igreja que escuta e caminha.\nA ti, Trindade, mistério supremo,\nnós te louvamos porque nos doaste\na nova aurora que o dia anuncia:\nCristo, que toda a criação glorifica.\nAntífonas e salmos do sábado da semana corrente.\nLEITURA BREVE Ap 12,3a.4cd.5-6a\nApareceu um outro sinal no céu: um dragão colocou-se diante da mulher que estava para dar à luz, a\nfim de lhe devorar o filho, tão logo nascesse. Ela deu à luz o filho, um varão, que irá reger todas as\nnações com um cetro de ferro.\nRESPONSÓRIO BREVE\nR. Rios de água alegram a cidade de Deus, * a morada santa do Altíssimo.\nV. Deus aí está: nunca a cidade será destruída.\nR. A morada santa do Altíssimo.\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Rios de água alegram a cidade de Deus, a morada santa do Altíssimo.\nCântico evangélico\nAnt. Ó Pai, vosso Filho unigénito tornou-se Filho de sua Serva e Senhor de sua Mãe: gerado por\nMaria e fruto da Igreja.\nOu: Feliz sois vós, ó Maria, mãe da glória e imagem resplendente da Igreja.\nPRECES\nConfiantes na ajuda da Virgem Maria, invoquemos com fervor o Pai que, pela força do Santo\nEspírito, conduz todos os homens à unidade. Digamos com fé:\nR. Senhor, fazei que todos formem uma só família.\nPai, por meio de Jesus Cristo conduzis os povos à vossa Igreja;\n- fazei que todos nela encontrem a vida.\nVós, na vinha do vosso povo, fizestes germinar a videira verdadeira que é Cristo;\n- ensinai-nos a permanecer unidos a ele.\nVós edificastes a Igreja como \"morada de Deus entre os homens\";\n- fazei que sejamos templos vivos da vossa divindade.\nO Pai, vós nos destes a Igreja como mãe carinhosa;\n- fazei que, na alegria deste novo dia, nos esforcemos para promover a unidade e a concórdia.\nPai Nosso...\nOração\nO Deus, que sois guia do povo eleito, quisestes que a Santa Virgem, Mãe de Cristo, cabeça da\nIgreja, fosse também mãe espiritual dos cristãos; por sua maternal intercessão, concedei que todos\nos povos se tornem vossa Igreja. Por nosso Senhor.", "form2Title": "MARIA E A IGREJA", "form3": "Invitatório\nAnt. Vinde, adoremos o Cristo Jesus: renova-se nele toda a criação.\nOu: Vinde, adoremos a Deus Pai, que em Cristo tudo renova.\nSalmo invitatório como no Ordinário, p. 35.\nOfício das Leituras\nHINO\n\"Grande sinal lá no céu aparece:\nmulher formosa vestida de sol,\npor sobre a lua descansa seus pés,\ncoroa de astros lhe enfeita a cabeça.\nLonge ela foge com asas de águia,\npara o deserto por Deus é levada\":\nvolta, ó Senhora, a gerá-lo de novo,\ne volte a terra inda ter esperança!\nA ti, Trindade, mistério supremo,\nnós te louvamos porque nos doaste\na nova aurora que o dia anuncia:\nCristo, que toda a criação glorifica.\nAntífonas, salmos, versículo e primeira leitura com respectivo responsório, do sábado da semana corrente.\nSEGUNDA LEITURA\nDos \"Discursos\" de João XXIII, papa (7 de dezembro de 1959)\nA intimidade do homem com Deus revela-se em Maria na sua perfeição original\nA Imaculada Conceição evoca os fulgores da aurora. Preservada de toda impureza original, Maria\nficou repleta de graça desde o primeiro instante de sua conceição. [Leitura completa disponível no\nofício impresso da Ordem.]\nRESPONSÓRIO\nR. Salve, Mulher Nova, preservada do pecado original: * de ti nasceu Cristo Jesus, novo Adão!\nV. Salve, Nova Terra, preparada por Deus, fecundada pelo Santo Espírito.\nR. De ti nasceu Cristo Jesus, novo Adão!\nLeitura alternativa\nDa Carta pastoral da Conferência dos Bispos das Ilhas Filipinas sobre a bem-aventurada Virgem\nMaria\nAs palavras de Maria preconizam uma mudança na ordem social do reino de Deus\nNa visitação (Lc 1,39-45.56) Maria, levando em seu seio o Menino, torna-se imagem da Arca da\nAliança e sede da presença permanente de Deus no meio do povo. [Leitura completa disponível no\nofício impresso da Ordem.]\nRESPONSÓRIO cf. Sl 33,4; 85,13; Lc 1,52\nR. Glorificai comigo o Senhor: * grande foi sua misericórdia.\nV. Depôs os poderosos dos seus tronos e exaltou os humildes.\nR. Grande foi sua misericórdia.\nOração\nO Deus, na Virgem-Mãe, plasmada pelo Espírito Santo, vós nos destes as primícias da nova criação;\nconcedei que, libertos da corrupção do pecado, nos transformemos em Cristo, Homem novo. Ele\nque convosco...\nLaudes\nHINO\n\"Humilde serva eu sou do Senhor,\nem mim se cumpram as tuas palavras\".\nTu és a terra obediente, ó Maria,\nterra que sabe, que ama e que adora.\nDia após dia a Igreja repita\nda humilde serva as sagradas palavras,\ne será tudo como era no início,\nquando o Senhor caminhava no Éden.\nGlória à Trindade, Pai, Filho e Espírito,\nque desde o início renovam o mundo:\npois foi-nos dada uma Virgem e Mãe,\nbeleza intacta de toda a criação.\nAntífonas e salmos do sábado da semana corrente.\nLEITURA BREVE cf. 2 Pd 3,13-14\nO que nós esperamos, conforme a sua promessa, são novos céus e nova terra, onde habitará a\njustiça. Assim, visto que tendes esta esperança, esforçai-vos ardorosamente para que ele vos\nencontre em paz, vivendo uma vida sem mácula e irrepreensível.\nRESPONSÓRIO BREVE\nR. Vi um novo céu e uma nova terra: * vi descer do céu, de junto de Deus, a cidade santa.\nV. Vi a nova Jerusalém, resplandecente da glória de Deus.\nR. Vi descer do céu, de junto de Deus, a cidade santa.\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Vi um novo céu e uma nova terra: vi descer do céu, de junto de Deus, a cidade santa.\nCântico evangélico\nAnt. Ave, Maria, puríssima Mãe de Deus! Ave, bendita! Tu concebeste o esplendor do Pai. Aleluia!\nOu: Grande é a tua glória, ó Maria, Mulher nova: de ti nasceu Cristo, o Homem novo!\nPRECES\nElevemos nossas súplicas a Deus Pai: na Santa Virgem Maria, mãe do novo Adão, ele nos deu a\nimagem e o início da Igreja. Digamos com fé:\nR. Senhor, renovai em nós o espírito de santidade!\nVós nos trouxestes à luz deste novo dia;\n- dai-nos ver a luz do dia em que todas as criaturas, libertadas da corrupção, haverão de\nconquistar a ditosa liberdade dos filhos de Deus.\nVós nos renovastes na água e no Espírito Santo;\n- fazei que caminhemos numa vida nova, coerentes com nosso batismo.\nNa Virgem Maria reparastes a antiga culpa de Eva;\n- concedei-nos respeitar a dignidade de todas as criaturas.\nPai Nosso...\nOração\nO Deus, na Virgem-Mãe, plasmada pelo Espírito Santo, vós nos destes as primícias da nova criação;\nconcedei que, libertos da corrupção do pecado, nos transformemos em Cristo, Homem novo. Ele\nque convosco...", "form3Title": "MARIA, MULHER NOVA", "form4": "Invitatório\nAnt. Vinde, exultemos no Senhor! Ele derrama sua misericórdia sobre aqueles que o temem.\nSalmo invitatório como no Ordinário, p. 35.\nOfício das Leituras\nHINO\nComo podermos cantar-te, ó Maria,\nsem ofender a tua santidade?\nsem perturbar o teu grande silêncio?\nNosso desejo é que peças por nós,\nnós cantaremos teu canto de amor:\nfaça-se em nós como tu declaraste.\nTu, chance última desta criação,\ntu, terra santa que o gera de novo,\ntu, tabernáculo vivo do Verbo.\nAntífonas, salmos, versículo e primeira leitura com respectivo responsório, do sábado da semana corrente.\nSEGUNDA LEITURA\nDos \"Sermões\" de São Boaventura, bispo\nCom grande confiança recorramos a Maria\n\"O meu Criador habitou sob a minha tenda\" (Eclo 24,12). Este versículo da Sagrada Escritura, no\nseu sentido literal, bem se aplica à Virgem Maria: em sua tenda habitou fisicamente o Senhor.\n[Leitura completa disponível no ofício impresso da Ordem.]\nRESPONSÓRIO\nR. Salve, regina de misericórdia, da vós nasceu o Cristo, nosso Rei: * intercedei para a nossa paz e\nsalvação.\nV. Salve, Mãe do Senhor, conforto do mundo, esperança dos pobres, refúgio dos fracos e oprimidos!\nR. Intercedei para a nossa paz e salvação.\nLeitura alternativa\nDo Tratado \"Sobre os louvores da B. Virgem Maria\", de Ricardo de São Lourenço, presbítero\nRainha e Mãe de misericórdia\nMaria é pródiga e cheia de misericórdia porque é rica e generosa. [Leitura completa disponível no\nofício impresso da Ordem.]\nRESPONSÓRIO\nR. Salve, Virgem piedosa, em vós nós esperamos! * Dia e noite a vós volvemos nosso olhar\nconfiante.\nV. Salve, rainha de misericórdia: por vossa clemência nos libertastes e vos entregastes a nós como\nmãe amável.\nR. Dia e noite a vós volvemos nosso olhar confiante.\nOração\nO Deus, Pai clemente e misericordioso, que fizestes da Virgem Maria a Arca da Nova Aliança, para\nque o Verbo viesse morar no meio dos homens; concedei-nos ser sempre fiéis à aliança que Cristo\nconfirmou com o seu sangue. Ele que é Deus...\nLaudes\nHINO\nÓ Mãe, tu foste das bodas à festa\njunto co'o Filho e também os discípulos:\noutro festim, porém, ele sonhava,\njá antevendo a colina sangrenta.\nSia gloria al Padre que o novo amor\normai ci dona da allora per sempre:\namor que solo o Filho revela\ne no Espírito é dado a quem ama.\nAntífonas e salmos do sábado da semana corrente.\nLEITURA BREVE Mq 7,18-20\nQual deus é como tu, que tira a culpa e perdoa o crime, que não guarda para sempre a sua ira,\nporque prefere o amor? Novamente ele nos manifestará a sua misericórdia, calcará aos pés as nossas\nfaltas e lançará no fundo do mar todos os nossos pecados.\nRESPONSÓRIO BREVE\nR. Lembrai-vos, Senhor, da vossa misericórdia, * como prometestes a nossos pais!\nV. Vossa misericórdia de geração em geração para aqueles que vos temem.\nR. Como prometestes a nossos pais!\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Lembrai-vos, Senhor, da vossa misericórdia, como prometestes a nossos pais!\nCântico evangélico\nAnt. Virgem santa, rainha da misericórdia e esperança do mundo, escutai os filhos que vos\ninvocam!\nPRECES\nBendigamos a Deus, Pai misericordioso que, em seu Filho Jesus Cristo, nascido da Virgem Maria,\nrealizou plenamente as suas promessas, e digamos com fé:\nR. Nós vos louvamos, Senhor, por vossa misericórdia!\nO Deus bondoso e paciente, que fecundastes o seio da Virgem Maria,\n- fazei que a vossa palavra, acolhida com fé, produza em nós frutos abundantes.\nO Deus justo e misericordioso, que escolhestes Maria dentre os humildes e pobres,\n- dai-nos um coração humilde e pobre para esperarmos confiantes a salvação que vem de Cristo.\nO Deus de misericórdia e de bondade, que nos concedestes ver a luz deste novo dia,\n- fazei que, à imitação da mãe de misericórdia, acolhamos com amor os que precisam de nós.\nPai Nosso...\nOração\nO Deus, Pai clemente e misericordioso, que fizestes da Virgem Maria a Arca da Nova Aliança, para\nque o Verbo viesse morar no meio dos homens; concedei-nos ser sempre fiéis à aliança que Cristo\nconfirmou com o seu sangue. Ele que é Deus...\nOu:\nSenhor, que enviastes o vosso Filho ao mundo para salvar os homens, dando-lhes Maria como Mãe\nde misericórdia, ouvi benigno as preces dos vossos servos que perante vós gemem sob o peso dos\nseus pecados e confiam na vossa clemência. Por nosso Senhor.", "form4Title": "MARIA, RAINHA DA MISERICÓRDIA", "form5": "Invitatório\nAnt. Vinde, adoremos o Senhor, que, por Santa Maria, visitou nossos povos.\nSalmo 94, como no Ordinário, p. 35.\nOfício das Leituras\nHINO\nAmas tua casa, és também peregrina,\ntu és esposa, tu mãe dedicada,\ntrilhas veredas por onde Deus passa,\ntudo o que ocorre tu logo percebes.\nSobes e desces, fiel ao teu \"sim\",\nlá no Calvário e em teu caminhar;\nrumo à morada celeste nós vamos,\nonde contigo queremos chegar.\nGlória a Deus Pai, o Senhor sempiterno,\nglória a Deus Filho, que é nosso Senhor\nao Santo Espírito consolador:\nassim aclame cantando o universo. Amém!\nAntífonas, salmos, versículo e primeira leitura do sábado da semana corrente.\nSEGUNDA LEITURA\nDo \"Documento de Puebla\" da III Conferência do Episcopado Latino-americano\nMaria faz com que a Igreja se sinta uma família\nEm nossos povos, o Evangelho tem sido anunciado, apresentando a Virgem Maria como sua\nrealização mais alta. Desde os primórdios - em sua aparição e invocação de Guadalupe - Maria\ntornou-se o grande sinal, de rosto materno e misericordioso, da proximidade do Pai e de Cristo.\n[Leitura completa disponível no ofício impresso da Ordem.]\nRESPONSÓRIO\nR. Salve, Serva do Senhor, Mãe de Deus! * Por vós o Evangelho foi proclamado aos nossos povos!\nV. Salve, mãe dos homens, fiel companheira do Senhor! Por vós a Igreja sente-se família.\nR. Por vós o Evangelho foi proclamado aos nossos povos!\nLeitura alternativa\nDo \"Nicán Mopohua\", relato do escritor indígena António Valeriano, do século XVI\nOuviu-se em nossa terra o cantar da rola\nNaquela estação, do ano de 1531, passados poucos dias do mês de dezembro, sucedeu que havia um\nindiozinho, um humilde homem do povo, de nome Juan Diego. Era sábado e, bem de madrugada,\nele vinha em busca de Deus e dos seus mandamentos. [Relato completo do encontro de Nossa\nSenhora de Guadalupe com Juan Diego disponível no ofício impresso da Ordem.]\nRESPONSÓRIO Ct 2,14; Ap 12,1\nR. Pomba minha, que se aninha nos vãos do rochedo, pela fenda dos barrancos, deixa-me ver tua\nface. * Deixa-me ouvir tua voz; pois tua face é tão formosa e tão doce a tua voz!\nV. Um sinal grandioso apareceu no céu: uma mulher vestida com o sol, tendo sobre a cabeça uma\ncoroa de doze estrelas.\nR. Deixa-me ouvir tua voz; pois tua face é tão formosa e tão doce a tua voz!\nOração\nSenhor, nosso Deus, que destes à América Latina a proteção maternal de Maria, Mãe do vosso\nFilho; dai-nos, por sua intercessão, ser firmes na fé e servir os irmãos com amor sincero. Por nosso\nSenhor.\nLaudes\nHINO\nMaria de Guadalupe\npelas trilhas de Juan Diego,\nSenhora de nossa América,\nvem cantando hoje teu povo!\nOlha p'ra nós, Mãe, e escuta:\num sonho acalenta a América\nque nasceu da tua promessa\npara os pobres e famintos.\nAntífona e salmos do sábado da semana corrente.\nLEITURA BREVE Is 52,7-10\nComo são belos sobre os montes os pés do mensageiro que anuncia a paz, que traz as boas novas e\nanuncia a libertação, que diz a Sião: Teu Deus reina!\nRESPONSÓRIO BREVE\nR. Diante dele * prostrar-se-ão todas as nações!\nV. Todos os povos o servirão.\nR. Prostrar-se-ão todas as nações!\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Diante dele prostrar-se-ão todas as nações!\nCântico evangélico\nAnt. Colocarei no meio de vós minha morada e enxugarei toda lágrima de vossos olhos. Como a\nmãe acaricia seu filho, assim eu os consolarei.\nPRECES\nUnidos a Santa Maria, Senhora da América Latina, elevemos nossa súplica a Cristo, evangelizador\npor excelência, e digamos juntos:\nR. Senhor da história, guiai os nossos passos!\nSenhor Jesus, Filho do Deus vivo, que proclamastes ao mundo a palavra que nos salva,\n- dai-nos a graça de nos comprometermos na obra da nova evangelização.\nSenhor Jesus, Bom Pastor, que guiais o rebanho pelos caminhos da justiça,\n- fazei que a Igreja latino-americana se torne de fato uma comunidade missionária.\nSenhor Jesus, nosso irmão, que lavastes os pés dos discípulos,\n- dai-nos coragem para nos comprometermos na promoção integral do povo latino-americano.\nPai Nosso...\nOração\nSenhor, nosso Deus, que destes à América Latina a proteção maternal de Maria, Mãe do vosso\nFilho; dai-nos, por sua intercessão, ser firmes na fé e servir os irmãos com amor sincero. Por nosso\nSenhor.", "form5Title": "SANTA MARIA DAS AMÉRICAS"}, "adoracao": "Adoração Eucarística\n\"Fala, que o teu servo escuta.\" 1Sm 3, 10\n1. Canto de Exposição do SS.\nSacramento\n2. Convite à Oração\nO sacerdote/diácono inicia a adoração solene ao Santíssimo\nSacramento: faz introdução e apresenta algumas motivações.\nDepois faz-se breve pausa e silêncio.\nD: Queridos irmãos, hoje nos reunimos diante do\nSantíssimo Sacramento para escutar e responder ao\nchamado de Deus em nossas vidas. Neste mês, somos\nconvidados a refletir sobre o tema ouvir e responder ao\nchamado de Deus, confirmando que o Senhor\nconstantemente nos chama a servi-Lo com\ngenerosidade e entrega.\nA exemplo dos nossos Primeiros Pais, que foram\nmovidos pelo Espírito a se comprometerem com o\ntestemunho do Evangelho e a comunhão fraterna, nós\ntambém somos chamados a servir a Deus e aos nossos\nirmãos e irmãs, inspirando-nos em Maria, a Mãe e\nServa do Senhor.\nNeste momento de adoração, peçamos a graça de ouvir\na voz de Deus em nosso coração e a coragem de\nresponder ao Seu chamado com fé e generosidade,\ncomo Maria respondeu com seu \"sim\". Que este tempo\ndiante do Senhor nos fortaleça para seguir Seu caminho\ncom alegria e fidelidade, sendo testemunhas de Seu\namor no mundo.\n3. Ato de Adoração\n(Orações do Anjo de Portugal ao Pastorinhos de\nFátima, em 1916)\nT: \"Meu Deus, eu creio, adoro, espero e amo-Vos.\nPeço-Vos perdão para os que não crêem, não\nadoram, não esperam e não Vos amam\".\n(Meditar alguns minutos em silêncio, pedindo ao\nSenhor a virtude da fé).\nT: \"Meu Deus, eu creio, adoro, espero e amo-Vos.\nPeço-Vos perdão para os que não crêem, não\nadoram, não esperam e não Vos amam\".\n(Meditar alguns minutos em silêncio, pedindo ao\nSenhor a virtude da esperança).\nT: \"Meu Deus, eu creio, adoro, espero e amo-Vos.\nPeço-Vos perdão para os que não crêem, não\nadoram, não esperam e não Vos amam\".\n(Meditar alguns minutos em silêncio, pedindo ao\nSenhor a virtude da caridade).\nT: Santíssima Trindade, Pai, Filho e Espírito Santo,\nadoro-Vos profundamente e ofereço-Vos o\npreciosíssimo Corpo, Sangue, Alma e Divindade de\nJesus Cristo, presente em todos os sacrários da\nterra, em reparação dos ultrajes, sacrilégios e\nindiferenças com que Ele mesmo é ofendido. E pelos\nméritos infinitos do Seu Santíssimo Coração e do\nCoração Imaculado de Maria, peço-Vos a\nconversão dos pobres pecadores.\n4. Canto\n5. Leitura Bíblica\nL1: O leitor lê da Bíblia, de pé, a perícope Bíblica:\n1 Samuel 3, 1-10.\n(Guardar silêncio para oração pessoal)\n6. Oração para Fazer Boa Escolha do\nEstado de Vida (adaptado)\nT: Ó Deus da sabedoria e do conselho, que ledes em\nmeu coração o desejo sincero de só a Vós servir, e\nde ordenar a minha vida segundo o vosso agrado:\nconcedei-me, por intercessão da Bem-aventurada\nVirgem Maria, minha mãe, e de todos os Santos,\nmeus advogados, especialmente nossos Sete Santos\nPais e São Filipe, a graça de conhecer o estado de\nvida que devo escolher e abraçar, de tornar-me apto\npara nêle procurar e aumentar a vossa glória,\ntrabalhar na salvação das almas, e assim merecer a\neterna recompensa, por Vós prometida aos que\ncumprem a vossa santíssima vontade. Assim seja.\n(Guardar silêncio para oração pessoal)\n7. Oração Vocacional\nD: Divino Salvador, que nos ensinastes a rezar:\n\"Mandai, Senhor, operários a vossa messe!\" dignai-vos\nsuscitar nas famílias cristãs muitas vocações\nsacerdotais e religiosas. Ilustrai a fé dos fiéis, a fim de\nque compreendam a grandeza desta santa vocação e\nfortalecei a vontade dos escolhidos, para que sejam\ngenerosos em seguir o vosso chamamento.\nT: Ofereço-Vos, Senhor, pelas mãos de nossa Mãe,\nMaria Santíssima: a adoração, terços, todas as\norações e trabalhos, todas as alegrias e sofrimentos\ndeste dia, pela santificação dos sacerdotes e pelas\nvocações sacerdotais e religiosas.\nD: Enviai, Senhor, à vossa Igreja.\nT: Santos sacerdotes e fervorosos religiosos!\nD: Senhor, dai-nos vocações religiosas. T: Senhor, dai-nos vocações religiosas.\nD: Senhor, dai-nos santas vocações religiosas. T:\nSenhor, dai-nos santas vocações religiosas.\nD: Sete Santos Fundadores, T: rogai por nós!\n8. Oração pelo Prior Geral e Prior\nProvincial\nD: Rezemos pelo nosso Prior Geral, Frei (Nome).\nMaria.\nT: Que o Senhor o ilumine e fortaleça em sua missão\nde guiar nossa Ordem, concedendo-lhe sabedoria e\ndiscernimento.\nD: \"Segui-me, e eu farei de vós pescadores de\nhomens.\" (Mt 4, 19)\nT: Que ele seja sempre um fiel seguidor de Cristo,\nnosso Mestre.\nD: Oremos: Deus Todo-Poderoso, derramai vossas\nbênçãos sobre Frei (nome). Maria, nosso Prior Geral.\nDai-lhe a coragem para liderar com justiça e\ncompaixão, inspirando-nos com seu exemplo de\nserviço e dedicação. Que ele conduza nossa Ordem\npelos caminhos da fé, esperança e caridade. Sob a\nproteção de Nossa Senhora, Mãe e Serva fiel, guardai-o e protegei-o em sua missão. Por Cristo nosso Senhor.\nT: Amém.\nD: Rezemos pelo nosso Prior Provincial, Frei (Nome).\nMaria.\nT: Que ele seja guiado pelo Espírito Santo em sua\nmissão, conduzindo-nos com sabedoria.\nD: \"Eis aqui a serva do Senhor. Faça-se em mim\nsegundo a tua palavra.\" (Lc 1, 38)\nT: Que ele, como Santa Maria, seja sempre fiel à\nvontade de Deus.\nD: Oremos: Ó Deus de bondade, derramai vossas\nbênçãos sobre Frei (Nome). Maria, nosso Prior\nProvincial. Enchei-o de vosso Espírito para que ele\npossa cumprir com alegria e dedicação sua missão de\ncuidar e orientar nossa província. Que seu ministério\nseja sempre um testemunho vivo do vosso amor e\nserviço. Pela intercessão de Nossa Senhora, Rainha dos\nServos, fortalecei-o e inspirai-o em sua caminhada. Por\nCristo, nosso Senhor.\nT: Amém.\nBênção do Santíssimo Sacramento\n(de joelhos)\n{TÃO SUBLIME VERÇÃO COMPLETA}\n(Vamos todos louvar juntos, o mistério de amor\nPois o preço deste mundo, foi o sangue redentor\nRecebido de Maria, que nos deu o salvador\nVeio ao mundo por Maria, foi por nós que ele nasceu\nEnsinou sua doutrina, com os homens conviveu\nNo final de sua vida um presente ele nos deu\nObservando a lei mosaica, se reuniu com os irmãos\nEra noite, despedida numa ceia, refeição\nDeu-se aos doze em alimento pelas suas próprias\nmãos\nA palavra do Deus vivo, transformou o vinho e pão\nNo seu sangue, no seu corpo, para nossa salvação\nO milagre nós não vemos, basta fé no coração\nTão sublime sacramento, adoremos neste altar\nPois o antigo testamento deu ao novo seu lugar\nVenha a fé por suplemento, os sentidos completar\nAo eterno pai cantemos e a Jesus, o salvador\nAo espírito exaltemos, na trindade eterno amor\nAo Deus uno e trino demos a alegria do louvor\nA alegria do louvor, alegria do louvor\nAmém!)\n{TÃO SUBLIME VERÇÃO BREVE}\nTão sublime Sacramento,\nadoremos neste altar.\npois o Antigo Testamento\ndeu ao Novo o seu lugar.\nVenha a fé por suplemento,\nos sentidos completar.\nAo eterno Pai cantemos\ne a Jesus, o redentor,\nAo Espírito exaltemos,\nna Trindade eterno amor.\nAo Deus uno e trino\ndemos a alegria do louvor. Amém!\nD: Do céu lhes destes o Pão. (T. P. Aleluia)\nT: Que contém todo sabor. (T.P. Aleluia)\nSacerdote: Oremos: Deus, que neste admirável\nSacramento, nos deixastes o memorial da vossa paixão,\nconcedei-nos tal veneração pelos sagrados mistérios do\nvosso Corpo e do vosso Sangue, que experimentemos\nsempre em nós a sua eficácia redentora. Vós, que viveis\ne reinais pelos séculos dos séculos.\nT: Amém.\n(Segue-se a bênção do Santíssimo Sacramento)\nD: Bendito seja Deus.\nT: Bendito seja o seu santo nome.\n- Bendito seja Jesus Cristo, verdadeiro Deus e\nverdadeiro homem.\n- Bendito seja o nome de Jesus.\n- Bendito seja o seu Sacratíssimo Coração.\n- Bendito seja o seu Preciosíssimo Sangue.\n- Bendito seja Jesus no Santíssimo Sacramento do\naltar.\n- Bendito seja o Espírito Santo Paráclito.\n- Bendita seja a grande mãe de Deus, Maria\nsantíssima.\n- Bendita seja sua santa e Imaculada Conceição.\n- Bendita seja sua gloriosa Assunção.\n- Bendito seja o nome de Maria, virgem e mãe.\n- Bendito seja são José, seu castíssimo esposo.\n- Bendito seja Deus, nos seus anjos e nos seus santos.\nD: Deus e Senhor nosso,\nT: protegei a vossa Igreja, dai-lhe santos pastores e\ndignos ministros. Derramai as vossas bênçãos sobre\no nosso Santo Padre, o papa, sobre o nosso bispo,\nsobre o nosso pároco e todo o clero, sobre o chefe da\nnação e do Estado e sobre todas as pessoas\nconstituídas em dignidade para que governem com\njustiça. Dai ao povo brasileiro paz constante e\nprosperidade completa. Favorecei com os efeitos\ncontínuos de vossa bondade o Brasil, este bispado, a\nparóquia em que habitamos, cada um de nós em\nparticular e todas as pessoas por quem somos\nobrigados a rezar ou que se recomendaram as\nnossas orações. Tende misericórdia das almas dos\nfiéis que padecem no purgatório. Dai-lhes, Senhor,\no descanso e a luz eterna.\n(Pai-Nosso, Ave-Maria e Glória ao Pai nas intenções do Santo Padre.)", "antifonas": "Antífonas finais de Nossa Senhora\n\nAo final das Vésperas (ou de todo o Ofício do dia), canta-se ou reza-se uma das seguintes antífonas marianas, conforme o tempo litúrgico:\n\nAlma Redemptoris Mater — Advento e Natal\nÓ Mãe do Redentor, do céu ó porta,\nao povo que caiu, socorre e exorta,\npois busca levantar-se, Virgem pura,\nnascendo o Criador da criatura:\ntem piedade de nós e ouve, suave,\no anjo te saudando com seu Ave!\n\n(Latim)\nAlma Redemptóris Mater,\nquae pérvia caeli porta manes,\net stella maris, succúrre cadénti,\nsúrgere qui curat, pópulo;\ntu quae genuísti, natura miránte,\ntuum sanctum Genitórem,\nVirgo prius ac postérius,\nGabriélis ab ore sumens illud Ave,\npeccatórum miserére.\n\nAve, Regina Cælorum — Quaresma\nAve, Rainha do céu;\nave, dos anjos Senhora;\nave, raiz, ave, porta;\nda luz do mundo és aurora.\nExulta, ó Virgem tão bela,\nas outras seguem-te após;\nnós te saudamos: adeus!\nE pede a Cristo por nós!\nVirgem Mãe, ó Maria!\n\n(Latim)\nAve, Regína caelórum\nave, Dómina angelórum,\nsalve, radix, salve, porta,\nex qua mundo lux est orta.\nGaude, Virgo gloriósa,\nsuper omnes speciósa;\nvale, o valde decóra,\net pro nobis Christum exóra.\n\nSalve, Regína — Tempo Comum\nSalve, Rainha, Mãe de misericórdia,\nvida doçura, esperança nossa, Salve!\nA vós bradamos os degredados filhos de Eva,\na vós suspiramos gemendo e chorando\nneste vale de lágrimas!\nEia, pois, Advogada nossa,\nesses vossos olhos misericordiosos a nós volvei,\ne depois deste desterro mostrai-nos Jesus,\nbendito fruto do vosso ventre!\nÓ clemente, ó piedosa,\nó doce sempre Virgem Maria.\n\n(Latim)\nSalve, Regína, mater misericórdiae;\nvita, dulcédo et spes nostra, salve.\nAd te clamámus, éxsules fílii Evae.\nAd te suspirámus, geméntes et flentes\nin hac lacrimárum valle.\nEia ergo, advocáta nostra,\nillos tuos misericórdes óculos\nad nos convérte.\nEt Iesum, benedíctum fructum ventris tui,\nnobis post hoc exsílium osténde.\nO clemens, o pia, o dulcis Virgo Maria.\n\nSub tuum praesídium — Qualquer tempo\nÀ vossa proteção recorremos, santa Mãe de Deus;\nnão desprezeis as nossas súplicas em nossas necessidades,\nmas livrai-nos sempre de todos os perigos,\nó Virgem gloriosa e bendita.\n\n(Latim)\nSub tuum praesídium confúgimus,\nsancta Dei Génitrix;\nnostras deprecatiónes ne despícias in necessitátibus,\nsed a perículis cunctis líbera nos semper,\nVirgo gloriósa et benedícta.\n\nSalve Rainha (versão cantada)\nSalve Rainha mãe de Deus,\nÉs Senhora nossa mãe, nossa doçura,\nNossa luz, doce Virgem Maria.\nNós a ti clamamos, filhos exilados,\nNós a ti voltamos nosso olhar confiante.\nVolta para nós, oh mãe,\nTeu semblante de amor.\nDá-nos teu Jesus, oh mãe,\nquando a noite passar.\nSalve Rainha mãe de Deus,\nÉs auxílio dos cristãos,\nOh mãe clemente, mãe piedosa,\nDoce Virgem Maria.\n\nSúplica dos Servos de Maria\nBondade, que nos abre o infinito,\ntesouro da graça Santa Mãe.\nInfunde em teus servos a esperança.\n\nVirtude, que com bondade nos socorre\nna incerta e difícil caminhada.\nDá-nos a fidelidade em teu serviço.\n\nReaviva em nós o antigo e sagrado compromisso\nde servir aos irmãos no amor,\ne com olhar fixo em ti seguir a Cristo!", "variasHome": [{"title": "Bênção da refeição", "text": "Comum\n Bendito sejais, Senhor Deus, nosso Pai, que\nfazeis germinar os frutos da terra, por estes dons que\ncolocastes sobre a nossa mesa. Abençoai aqueles que,\ncom seu trabalho, os cultivaram, os que os prepararam\ncomo alimento e a nós que estamos para recebê-los\ncom o coração agradecido, enquanto esperamos\nencontrar-nos um dia todos reunidos no vosso Reino\neterno. Por Cristo nosso Senhor. Amém!\nNas festas marianas\n\n Senhor Deus, nosso Pai, que na Virgem Maria\ndestes à Igreja a imagem profética do seu futuro;\nabençoai a nós e ao alimento que estamos para tomar e\nfazei que, celebrando hoje a bendita entre as mulheres,\npossamos refletir em nós sua vida de obediência e de\namor. Por Cristo nosso Senhor. Amém!\nNas visitas de familiares e amigos\n Senhor nosso Deus, que de muitas maneiras\nconvidais os seres humanos, ajudai-nos a compreender\no dom da graça da hospitalidade, para que saibamos\nreconhecer a vossa presença no irmão que nos visita.\nSede bendito agora e sempre. Amém!\n\nNos momentos de alegria\n Ó Deus, fonte da alegria, por meio do vosso\nFilho, nos fazeis participar das vossas maravilhas: nós\nvos bendizemos pelos dons do vosso amor, em modo\nparticular hoje ...[explicitar o motivo da alegria], e vos\npedimos que transformeis as alegrias deste dia em\njúbilo perene no céu. Por Cristo nosso Senhor. Amém!"}, {"title": "Pelas vocações", "text": "I. Ó Maria, que chamastes os nossos Sete Santos\nPais e, ao longo dos séculos, tantos outros homens e\nmulheres, para servir a Cristo e aos irmãos, inspirando-\nse no Evangelho e no vosso exemplo, concedei-nos\nhoje também a graça de muitas vocações para a vossa\nOrdem.\n Fazei que a nossa Família seja sempre a casa por\nvós abençoada e amada, de modo que, quantos a\nescolherem como sua morada, vivam generosamente os\nensinamentos do vosso Filho e se coloquem\ninteiramente a serviço da Igreja e dos seres humanos.\nAmém!\n II. Senhor, humildemente vos pedimos: concedei\nque os Servos e as Servas de Santa Maria vivam uma\nvida fraterna e santa e se tornem neste mundo\ntestemunhas de bondade e de misericórdia.\n\n Que as nossas comunidades e fraternidades sejam\ncaminho, ponte e sinal para os que desejam ir ao vosso\nencontro; sejam luz para os que precisam de luz, paz\npara os que buscam a paz e serviço para os que dele\nprecisam; sejam apelo à oração, fraternidade que\nliberta os seres humanos da solidão e lugar onde a luz\ndo Ressuscitado se irradie em formas de vida humana.\nAmém!"}, {"title": "Pelas missões", "text": "Ó Virgem Maria, Rainha dos apóstolos,\nchamastes os nossos Santos Primeiros Pais ao\nseguimento do vosso Filho Jesus e os enviastes no meio\ndos homens para testemunhar o Evangelho em\ncomunhão fraterna.\n Acompanhai e guiai os nossos irmãos e irmãs que\nassumiram o compromisso de irradiar no mundo o\ncarisma da nossa vocação, e intercedei por nós junto ao\nSenhor, para que a grande messe da humanidade possa\ncontar com operários dignos e em número suficiente\npara a colheita. Amém!"}, {"title": "Pelos doentes", "text": "Ó Deus misericordioso, salvação eterna dos que\ncreem, escutai as preces que vos fazemos por...[diz-se\no nome do(a) doente] e fazei que ele (ela) volte ao\nconvívio da vossa Igreja onde possa render-vos graças\n\ne proclamar as vossas maravilhas. Por Cristo nosso\nSenhor. Amém!"}, {"title": "Pelos defuntos", "text": "Antífona\n\n Senhor, fonte de luz, iluminai as minhas trevas.\nLibertados pelo amor de Cristo, possamos esperar a\nvida eterna. Outros me haviam falado de vós, mas\nagora meus olhos vos veem.\n\nSalmo 129\n- Das profundezas, Senhor, a ti eu clamo. *\n Senhor, escuta o meu apelo;\n- teus ouvidos estejam bem atentos *\n ao clamor de minha súplica.\n- Se levares em conta, Senhor, nossas faltas, *\n Senhor, quem poderá subsistir?\n- Mas em ti encontra-se o perdão, *\n eu temo e espero.\n\n- Minha alma espera no Senhor, *\n em sua palavra tenho confiança;\n- minha alma espera pelo Senhor, *\n mais confiante do que o vigia\n\n esperando pela aurora.\n\n- Que o vigia espere pela aurora, *\n e Israel pelo Senhor.\n\n- Porque no Senhor encontra-se a graça, *\n copiosa redenção\n- é ele quem redimirá Israel *\n de todas as suas faltas.\nOração [reza-se uma das seguintes orações]\n I. Pai Santo, luz e salvação dos homens, vós nos\nrevelastes as riquezas do vosso amor através do mundo\ncriado e, sobretudo, em vosso próprio Filho.\n Concedei, pois, que nossos irmãos e irmãs\ndefuntos, que viveram em comunhão fraterna na busca\nda vossa face, possam entrar em vossa morada e\ncontemplar o que sempre desejaram ver.\n E a nós, que continuamos a buscar-vos, concedei a\ngraça de fortalecer a nossa esperança e de recobrar\nnovo alento no caminho que conduz à terra dos vivos.\nPor Cristo nosso Senhor. Amém!\n II. Ó Deus, em Cristo vosso Filho, destes aos\nhomens, peregrinos nesta terra, o penhor de uma segura\nesperança e a fonte da água viva.\n Sede benigno com os nossos irmãos e irmãs que,\ntendo completado sua peregrinação terrena, partiram\ndeste mundo rumo à morada eterna.\n\n Saciai com vosso amor a sede que eles têm de vós\ne introduzi-os em vossa casa, onde sejam festivamente\nrecebidos no convívio dos santos. Por Cristo nosso\nSenhor. Amém!\n\n III. Senhor, vós conheceis a fraqueza humana e,\ncomo Pai bondoso e rico em misericórdia, não vos\ncansais de esperar nosso retorno para abraçar-nos e dar-\nnos o vosso perdão.\n Tende piedade dos nossos irmãos e irmãs que,\ninvestidos pelo vento da morte, tirastes do meio de nós.\nDai-lhes, Senhor, descanso junto a vós, para que, com\na Virgem Mãe e com os irmãos já transfigurados por\nvosso amor, possam louvar eternamente a vossa\nmisericórdia. Por Cristo nosso Senhor. Amém!"}, {"title": "Bem-aventurada Virgem Maria ao Pé da Cruz", "sub": "Sexta-feira depois do V Domingo de Quaresma", "text": "Festa\nInvitatório\nAnt. Vinde, adoremos o Redentor do mundo: junto à cruz está sua mãe, mergulhada num vale de lágrimas.\nSalmo invitatório, como no Ordinário, p. 35. Ofício das Leituras\n\nHino\n\nA Mãe estava de pé junto à cruz,\num pouco à parte e envolta em silêncio, qual uma sombra de negro vestida: tudo era imóvel e o vento parado.\n\nPerdida, ao longe fixava sua vista: ó Mãe, que vias do alto do Monte?\nVias talvez uma selva de cruzes\nou tu também nada mais percebias?\n\nTu és, ó Mãe, toda a mãe que hoje ama, tu és, ó Mãe, toda a mãe que hoje chora seu filho morto, seu filho traído:\nmães aos milhares, mães amortalhadas!\n\nFilhos que sempre se estão a matar, filhos vendidos, traídos sem número, filhos feridos e em cruzes pregados, ímpia bandeira de um ímpio poder.\n\nJá densas trevas cobriam a cidade, inda mais pálido fez-se seu rosto; todo seu corpo coberto de sangue rubro de sangue também era o céu,\n\nqual lençol negro de sangue estirado, para envolver sua Ausência infinita, que inda mais triste o silêncio a tornava e se adensava e fluía nos ares.\n\nNada pedimos, ó Mãe, para nós: crermos apenas, por quanto possível, e junto à cruz ao teu lado ficarmos:\nesta é a resposta ao mistério do mundo.\n\nSalmodia\nEscolhe-se uma das séries de antífonas seguintes.\nAnt. 1\n    A. Perto da cruz de Jesus estava sua mãe, firme na fé, forte na esperança e ardente na caridade.\n    B. Vós, Senhor, sois o escudo que me protege e o consolo em minha amargura.\n    C. Enquanto Cristo se oferece ao Pai em oblação, Maria se associa a ele pela fé.\nSalmo 3\nMorte e ressurreição do justo\nAquele que eles fizeram perecer, suspendendo-o na cruz, Deus o ressuscitou ao terceiro dia (At 10,39-40).\nQuão numerosos, ó Senhor, os que me atacam; * quanta gente se levanta contra mim!\nMuitos dizem, comentando a meu respeito: * \"Ele não acha a salvação junto a Deus!\"\nMas vós sois o meu escudo protetor, *\na minha glória que levanta minha cabeça! Quando eu chamei em alta voz pelo Senhor, * do monte santo ele me ouviu e respondeu.\nEu me deito e adormeço bem tranquilo; * acordo em paz, pois o Senhor é meu sustento.\n    • Não terei medo de milhares que me cerquem, * e furiosos se levantem contra mim.\n= Levantai-vos, ó Senhor, vinde salvar-me! †\nVós que feristes em seu rosto os que me atacam, * e quebrastes aos malvados os seus dentes.\n    • Em vós, Senhor, nós encontramos salvação; * e repouse a vossa bênção sobre o povo!\nAnt. 1\n    A. Perto da cruz de Jesus estava sua mãe: firme na fé, forte na esperança e ardente na caridade.\n    B. Vós, Senhor, sois o escudo que me protege e o conso lo em minha amargura.\n    C. Enquanto Cristo se oferece ao Pai em oblação, Maria se associa a ele pela fé.\n\nOração sálmica\nOuvi, Senhor, do vosso santo monte, a súplica de quem vos invoca; derramai sobre nós a bênção que Jesus nos mereceu na cruz e confirmai-nos na esperança da salvação, que ele proclamou ao ressuscitar dos mortos. Pelo mesmo Cristo nosso Senhor.\nAnt.2\n    A. Todos fogem, mas a mãe de Jesus permanece firme de pé junto à cruz.\n    B. Voltai para mim vosso olhar, Senhor, e respondei-me: eu confio em vossa misericórdia.\n    C. Da árvore, Eva colhe o fruto da morte e o oferece ao homem; do madeiro da cruz, Maria colhe o alimento da vida e oferece-o a toda a humanidade.\n\nSalmo 12\nLamentação do justo que confia em Deus.\nNa esperança fomos salvos (Rm 8,24).\n- Até quando, ó Senhor, me esquecereis? * Até quando escondereis a vossa face?\n= Até quando estará triste a minha alma? † e o coração angustiado cada dia? *\nAté quando o inimigo se erguerá?\n= Olhai, Senhor meu Deus, e respondei-me! † Não deixeis que se me apague a luz dos olhos * e se fechem, pela morte, adormecidos.\n= Que o inimigo não me diga: \"Eu triunfei!\" Nem exulte o opressor por minha queda, * uma vez que confiei no vosso amor!\n\nMeu coração, por vosso auxílio, rejubile, *\ne que eu vos cante pelo bem que me fizestes.\nAnt.2\n    A. Todos fogem, mas a Mãe de Jesus permanece firme de pé junto à cruz.\n    B. Voltai para mim vosso olhar, Senhor, e respondei-me: eu confio em vossa misericórdia.\n    C. Da árvore, Eva colhe o fruto da morte e o oferece ao homem; do madeiro da cruz, Maria colhe o alimento da vida e oferece-o a toda a humanidade.\nOração sálmica\nO Deus, gravai em nosso coração a lembrança da paixão do vosso Filho e das dores de sua Mãe: na hora da provação, despertai em nós seus mesmos sentimentos para que, confiantes em vossa misericórdia, possamos alegrar-nos pelo dom da vossa salvação. Por Cristo nosso Senhor.\nAnt. 3\n    A. Sua Mãe, em prantos, permanece junto à cruz: sua dor é maior que o martírio.\n    B. Diante dos ímpios que me oprimem, guardai-me, Senhor, qual pupila de vossos olhos.\n    C. Junto à cruz, Maria aceita como filhos todos os ho mens que Deus, em seu amor, lhe confiara.\nSalmo 16\nDeus, esperança do inocente perseguido\nJesus, cheio de angústias, orava com maior insistência (Lc 22,43).\n    • Ó Senhor, ouvi a minha justa causa, * escutai-me e atendei o meu clamor!\n    • Inclinai o vosso ouvido à minha prece, pois não existe falsidade em meus lábios!\n    • De vossa face é que me venha o julgamento, * pois vossos olhos sabem ver o que é justo.\n= Provai meu coração durante a noite, † visitai-o, examinai-o pelo fogo, *\nmas em mim não achareis iniquidade.\n    • Não cometi nenhum pecado por palavras, * como é costume acontecer em meio aos homens.\n    • Seguindo as palavras que dissestes, * andei sempre nos caminhos da Aliança.\n    • Os meus passos eu firmei na vossa estrada, * e por isso os meus pés não vacilaram.\n    • Eu vos chamo, ó meu Deus, porque me ouvis, * inclinai o vosso ouvido e escutai-me.\n= Mostrai-me vosso amor maravilhoso, † vós que salvais e libertais do inimigo * quem procura a proteção junto a vós.\n    • Protegei-me qual dos olhos a pupila * e guardai-me, à proteção de vossa asas,\n    • longe dos ímpios violentos que me oprimem, * dos inimigos furiosos que me cercam.\n    • A abundância lhes fechou o coração, * em sua boca há só palavras orgulhosas.\n    • Os seus passos me perseguem, já me cercam, * voltam seus olhos contra mim: vão derrubar-me,\n    • como um leão impaciente pela presa, * um leãozinho espreitando de emboscada.\n    • Levantai-vos, ó Senhor, contra o malvado, * com vossa espada abatei-o e libertai-me!\n    • Com vosso braço defendei-me desses homens, * que já encontram nesta vida a recompensa.\n= Saciais com vossos bens os ventres deles, † e os seus filhos também hão de saciar-se *\ne ainda as sobras deixarão aos descendentes.\n    • Mas eu verei, justificado, a vossa face * e ao despertar me saciará vossa presença.\nAnt.3\n    A. Sua Mãe, em prantos, permanece junto à Cruz: sua dor é maior que o martírio.\n    B. Diante dos ímpios que me oprimem, guardai-me, Senhor, qual pupila dos vossos olhos.\n    C. Junto à cruz, Maria aceita como filhos todos os homens que Deus, em seu amor, lhe confiara.\nOração sálmica\nAtendei, ó Pai, a súplica que vosso Filho vos faz do alto da cruz: irmão nosso, ele pede por nós; inocente, intercede pelos pecadores. Reconciliados por ele, possamos nós também contemplar vossa face e, no último dia, ao despertar do sono da morte, saciar-nos da vossa presença. Por Cristo nosso Senhor.\nV. Ouvi, povos todos, e vede minha dor.\nR. O Senhor deixou-me desolada e amargurada para sempre.\n\nPrimeira leitura\nDo livro do profeta Isaías (52,13-53.12)\nEle foi traspassado por causa de nossas transgressões\nEis que meu servo será bem sucedido; subirá, será exaltado e elevado bem alto. Assim como muitos se sentiram horrorizados à vista dele - tão desfigurado ele estava que já não parecia homem e seu aspecto já não era o de seres mortais - do mesmo modo muitos povos se admiram, diante dele os reis ficam mudos; pois vêem algo que jamais lhes foi contado, e chegam a saber o que nunca tinham ouvido.\nQuem deu crédito ao que nos era anunciado, e a quem o braço do Senhor foi revelado? Ele vegetava na sua presença como um rebento, como raiz em terra seca: não tinha beleza nem formosura que atraísse os nossos olhares, não tinha apresentação para que desejássemos vê-lo. Era desprezado, era o refugo da humanidade, homem das dores e habituado à enfermidade; era como pessoa de quem se desvia o rosto, tão desprezível que não fizemos caso dele.\nNo entanto, foi ele que carregou as nossas enfermidades, e tomou sobre si as nossas dores. E nós o considerávamos como alguém fulminado, castigado por Deus e humilhado. Mas ele foi traspassado por causa das nossas re-beldias, esmagado por causa dos nossos crimes; caiu sobre ele o castigo que nos salva, e suas feridas nos curaram.\nTodos nós andávamos extraviados como ovelhas, cada um de nós se desviava para o próprio caminho, mas o Senhor fez cair sobre ele a iniquidade de todos nós. Maltratado, ele se humilhava e não abria a boca. Foi eliminado por um julgamento violento, e quem se preocupa com sua sorte? De fato, foi exterminado do país dos vivos; por causa da rebeldia de meu povo foi golpeado de morte. Deram-lhe sepultura em meio aos ímpios e seu túmulo está com os ricos, embora não tivesse praticado violência, nem houvesse falsidade em sua boca. Mas o Senhor quis esmagá-lo com a doença: se fizer de sua vida um sacrifício expiatório, ele verá sua descendência, prolongará seus dias, e a causa do Senhor triunfará graças a ele. Depois de profundos sofrimentos, ele verá a luz, sentir-se-á satisfeito; com seu conhecimento, meu Servo justo justificará a muitos, e tomará sobre si as suas iniquidades.\nPor isso lhe darei uma parte entre os grandes, e com os poderosos ele partilhará os despojos; é que entregou sua vida à morte e se deixou contar entre os rebeldes, quando na realidade carregava o pecado de muitos e intervinha em favor dos rebeldes.\nRESPONSÓRIO Is53,4a.5.6b\nR. Ele carregou as nossas enfermidades e tomou sobre si as nossas dores. Foi traspassado por causa das nossas rebeldias e esmagado por causa dos nossos crimes. * Suas feridas nos curaram.\nV. O Senhor fez cair sobre ele a iniquidade de todos nós.\nR. Suas feridas nos curaram.\nSegunda leitura\nDas \"Homilias\" de Santo Amadeu de Lousana, bispo (Hom. V de laudibus b. Mariae V., passim; SC 72, p. 138-156)\nEstava junto à cruz mergulhada num vale de lágrimas\nHá dois tipos de martírio: um é externo, outro não; um é conhecido, outro não; um atormenta a carne, outro aflige a alma. Os apóstolos e os mártires passaram pelo martírio da carne, sacrificando suas vidas por amor à verdade e testemunhando a pessoa de Jesus. Vítimas por causa de Cristo, tomaram o cálice do Senhor e mereceram subir para a glória do céu pela cruz, e participar da vida eterna pela morte temporal.\nAo contrário, padeceram o martírio no espírito aqueles que suportaram em sua alma dores mais atrozes do que o sofrimento do corpo. Abraão sofreu no espírito, quando Deus lhe pediu que sacrificasse o seu filho Isaque, que tanto amava. Angustiava-se pelo intenso afeto paternal e pelo profundo amor que tinha para o filho. A gloriosa Virgem Maria passou pelo mesmo sofrimento, quando estava ao pé da cruz do Senhor. Mais próxima à cruz do que os outros, tornou-se mais bemaventurada.\nTomou o cálice, sofreu toda a paixão e, mitigando a sede na torrente da dor, suportou um sofrimento sem par. Ela seguiu Jesus, não apenas na alegria das consolações, mas também na angústia dos sofrimentos.\nEstava, pois, junto à cruz, contemplando o triste espetá-culo da cabeça do seu amado Filho, ungida com óleo entre os seus companheiros (SI 44,8), espancada com caniço e coroada de espinhos. Ela via seu Filho, o mais belo entre os filhos dos homens, sem nenhuma aparência humana e sem dignidade. Via o mais excelso entre todos desprezado e exposto à execração pública. Via o santo dos santos crucificado entre dois malfeitores. Via os olhos do homem mais insigne sendo humilhados. Via a cabeça daquele que tudo sustenta, caída sobre o ombro. Via a face de Deus desfigurada e sua beleza extinta.\nO santa memória, repleta de piedade e de lágrimas! Recordar o sofrimento glorioso desta santa alma e as angústias suportadas na morte de Cristo, enche-nos de amor por ela! A palidez do rosto de Jesus refletia-se no rosto de Maria. Ele padecia na carne, ela no coração. A morte do Senhor foi para ela mais amarga que a sua própria morte. Iluminada pelo Espírito Santo, Maria não duvidava que o Filho haveria de ressuscitar. Todavia, foi necessário beber o cálice do Pai e viver até o fim a Paixão. Esses acontecimentos foram profetizados pelo velho Simeão quando disse: \"Uma espada traspassará tua alma\" (Lc 2,35). Senhor Jesus, nem sequer tua Mãe poupaste da espada que lhe traspassou o coração!\nMaria podia, pois, fazer suas as palavras que se aplicam primeiramente a Cristo: \"O vós todos que passais pelo caminho, olhai e vede se há dor semelhante à minha dor!\" (Lm 1,12). Grande foi a dor de Maria e grande foi Maria na dor! Tudo era diferente do dia em que venerou o Filho, aclamado pelo coro dos anjos, glorificado pelos pastores e adorado pelos magos, que lhe ofereciam místicos dons! Agora, tudo era diferente: não, porém, na virtude, mas na tristeza; não na graça, mas na aflição. Ao pé da cruz, Maria crescia na virtude e se fortalecia na graça.\nCaríssimos, nas dificuldades imitemos a Mãe do Senhor e lembremos sua postura e sua fortaleza diante do sofrimento.\nRESPONSÓRIO\nR. Enquanto Jesus morria na cruz, Maria lá estava, sofrendo o martírio no coração. * Sustentada pelo amor maternal, ela abraçava a cruz do Filho.\nV. Uma lança traspassou o lado de Cristo; uma espada traspassou a alma de Maria.\nR. Sustentada pelo amor maternal, ela abraçava a cruz do Filho.\nLeitura alternativa\nDo Tratado \"Sobre o triunfo de Cristo\", de São Lourenço Giustiniani, bispo (Cap. 18; Opera omnia, ed. Venetiis 1720, p. 271-272)\nA ti eu confio minha Igreja na pessoa do discípulo\nNo Calvário, em tudo Maria via sinais da dor cruel que estava sofrendo. Mesmo assim, permanecia firme ao pé da cruz. Aí, como por um tríplice laço, sentia-se presa pela dor, pelo espanto e pelo amor.\nPela dor, porque a espada da paixão do Filho lhe traspassava a alma. E para onde ir com uma espada a traspas-sar-lhe a alma, e crucificada ela própria no coração?\nPelo espanto, porque, em silêncio, meditava sobre o Filho suspenso na cruz. Sabia que ele era o verdadeiro Deus e, portanto, por sua natureza, imune do sofrimento, imortal, invisível e santo. E quando meditava dentro de si essas verdades, e se deva conta que ele era ao mesmo tempo sujeito à dor e imune dela, mortal e imortal, visível e invisível, frágil e glorioso mais que todos, o espanto tomava conta dela. Como podia ficar atónita e imóvel pelo espanto? Quem perscruta a majestade divina - diz a Escritura -fica absorvido pela luz de sua glória (cf. Pr 25,27).\nPelo amor, por fim, porque tinha um só Filho, o mais belo e mais santo de todos, rico de virtudes e repleto de graças, ao qual estava intimamente ligada pelos laços do amor maternal.\nO espanto e o amor eram como dois riachos que fluíam sem parar até o rio da dor, e daí, qual torrente impetuosa de aflição, desaguava no coração da Virgem Maria. Por isso, nela aconteceu o que se lê nas Lamentações de Jeremias: \"O vós todos que passais pelo caminho, olhai e vede se existe dor igual à dor que me atormenta\" (Lm 1,12).\nJesus via sua Mãe abatida sob o pesado fardo da dor e, a seu lado, o discípulo amado que a consolava. Movido de compaixão, condoeu-se pelos dois mais do que sofria por suas próprias dores. Por isso, disse à Mãe: \"Mulher, eis aí teu filho\" (Jo 19,26). Entrego-te como filho o discípulo predileto, para que permaneça contigo: ele te obedecerá como filho, e nele, assim como em mim, encontrarás consolo.\nA entrega que te faço do discípulo encerra em si um mistério admirável. Ele representa, com efeito, a Igreja, virgem e pura. Eu a entrego a ti, na pessoa do discípulo. Ama-a, assim como me amas. Fortalece-a com tuas exortações. Anima-a com teus conselhos e ensina-lhe com teus exemplos. Quero que tu a tenhas em conta de filha; prote-ge-a com tuas orações e orienta-a para mim, enriquecida de todas as virtudes. A ela pedirei que te venere como mãe, te ame e encontre em ti o seu refúgio.\nDepois disse ao discípulo: \"Eis aí tua mãe\" (Jo 19,27). Serve-a, honra-a e toma meu lugar junto a ela. Qualquer reverência ou homenagem feita a ela, eu a considero feita a mim. Neste momento de aflição, conforta-a, sê-lhe amigo fiel e filho obediente.\nDepois de pronunciar essas palavras, intensificando-se a agonia da paixão e aproximando-se a hora da morte, ele se calou. A partir de então, segundo a ordem do Senhor, o discípulo a levou para sua casa (cf. Jo 19,27).\nRESPONSÓRIO\nR. Maria, aflita junto à cruz do Senhor, recebeu o testamento do amor de Deus: * tornou-se mãe de todos os homens.\nV. A todos ela abraça com amor de mãe, estejam ou não conscientes da redenção de Cristo.\nR. Tornou-se mãe de todos os homens.\nHino Te Deum, p. 36. Oração\nO Deus, quisestes que junto à cruz do vosso Filho estivesse sua Mãe, compartilhando de sua paixão. Guardai e aumentai na família humana os frutos de tão grande mistério. Por nosso Senhor.\nOu:\nO Deus, por vosso admirável desígnio, dispusestes prolongar a Paixão do vosso Filho nas infinitas cruzes da humanidade. Nós vos pedimos: assim como quisestes que ao pé da cruz de Jesus estivesse sua Mãe como companheira na dor, nós também, a exemplo da Virgem das Dores, possamos estar sempre ao lado dos irmãos que sofrem, para le-var-lhes conforto e esperança de libertação. Por nosso Senhor...\n\n\nLaudes\nHino\n\nEis que o silêncio no céu se propaga desde que o sangue parou de escorrer: ora até o Filho, inda vivo, emudece, enquanto a Mãe já há tempo calara.\nTodos agora parecem calar-se:\nvós que sois justos, tomai a palavra! O Mãe do justo, por que tu não falas?\nCumpre-se assim o mistério do mundo.\nQuando lançou o seu último grito, eis que do templo a cortina se rasga de cima a baixo, e a terra tremeu; grito como este jamais se escutara!\nAbrem-se então os sepulcros e as rochas, pelas estradas os mortos vagueiam:\nde corpos santos e brancos fantasmas vê-se invadida a cidade maldita.\nTudo mergulha nas trevas escuras da negra noite que cai sobre a terra:\ntão tenebrosa é a ausência de Deus, esta é a noite que a todos envolve.\nA Mãe também mergulhada nas trevas? Ela sozinha por nós todos crê: nós,\nao invés, hesitantes ficamos, sem decidir entre o medo e a fé.\nEscuta, ó Mãe, entre tanta miséria,\nos que confessam num grito incontido:\nFilho de Deus verdadeiro ele era e toda vítima é sempre teu filho.\nSALMODIA\nAnt. 1 Se morrermos com Cristo, nós cremos que com ele haveremos de viver.\nSalmos e cântico do domingo da Ia semana, p. 514.\n\nAnt. 2 Trazemos sempre em nosso corpo a morte de Jesus, a fim de que sua vida em nós se manifeste.\nAnt. 3 A mensagem da cruz é loucura para os que se opõem a Deus, mas é poder divino para os que buscam a salvação.\n\nLEITURA BREVE Zc 12,10\nDerramarei sobre a casa de Davi e sobre todo o habitante de Jerusalém um espírito de graça e de súplica, e eles olharão para mim. Quanto ao que traspassaram, eles o lamentarão como na lamentação de um filho único; eles chorarão como se chora o primogénito.\n\nRESPONSÓRIO BREVE\nR. Eis o Senhor que vem entre as nuvens e hão de vê-lo todos aqueles que o traspassaram. * E sobre ele hão de chorar todas as nações da terra.\nV. Eis o Cordeiro imolado, que tira o pecado do mundo.\nR. E sobre ele hão de chorar todas as nações.\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Eis que o Senhor vem entre as nuvens e hão de vê-lo todos aqueles que o traspassaram. E sobre\nele hão de chorar todas as nações da terra.\n\nCântico evangélico\nAnt. Alegra-te agora, santa Mãe, tu que sempre estiveste intimamente unida ao Filho: com o sacrifício do teu coração no Calvário, tu o ofereceste ao Pai para a salvação de todos os povos.\nPreces\nElevemos nossas súplicas a Deus Pai, criador da vida, que, para salvar o mundo, associou a seu Filho a Virgem Maria, mulher forte. Digamos juntos:\n\nR. Salvai-nos, ó Deus, por vosso amor!\nPai, vosso Filho, nascido da Virgem Maria, é luz dos povos e sinal de contradição;\n    • concedei-nos que, caminhando pelas estradas do mundo, sigamos a Cristo, luz nas trevas, e o tenhamos sempre como nosso guia.\nPai, muitos rejeitam vosso Filho, Salvador do mundo, assim como no passado foram rejeitados os profetas;\n    • fazei que o acolhamos sempre de braços abertos em nossas casas.\nPai, vós concedestes um profundo espírito de fé a Maria, quando estava junto à cruz do Filho;\n    • dai-nos enxugar as lágrimas de nossos irmãos, transmi tindo-lhes esperança, e afastar o seu medo, suscitando a fé.\nMaria, Mãe de Cristo, esteve ao lado da igreja primitiva, massacrada pela perseguição;\n    • como ela, ajudai-nos a caminhar, ao lado dos pobres e oprimidos, rumo à conquista da tão esperada e sofrida liberdade.\nO pai, vós nunca nos impondes um peso superior às nossas forças;\n    • fazei que compreendamos o valor da nossa cruz e pos samos carregá-la confortados por Maria nossa Mãe.\n[A exemplo de Cristo que, pregado na cruz, abandonou-se à vontade do Pai e rezou por seus algozes, nós também supliquemos o Pai celestial, dizendo: Pai nosso...].\n\nOração\nO Deus, quisestes que junto à cruz do vosso Filho estivesse sua Mãe, compartilhando de sua Paixão. Guardai e aumentai na família humana os frutos de tão grande mistério. Por nosso Senhor...\n\nOu:\nO Deus, por vosso admirável desígnio, dispusestes prolongar a Paixão do vosso Filho nas infinitas cruzes da humanidade. Nós vos pedimos: assim como quisestes que ao pé da Cruz de Jesus estivesse sua Mãe como companheira na dor, nós também possamos estar sempre ao lado dos irmãos que sofrem, para levar-lhes conforto e esperança de libertação. Por nosso Senhor...\n\n\nHora Média\nAntífonas e salmos do dia da semana corrente. Hinos como no Ordinário, p. 40.\n\nOração das Nove Horas\nLEITURA BREVE Lm 1,12a\nÓ vós todos que passais pelo caminho, olhai e vede: há dor semelhante à minha dor? Como me maltrataram! O Senhor me afligiu no dia da sua ardente ira.\nV. Senhor, eu vos abri meu coração,\nR. e vós tivestes piedade de minhas lágrimas.\nOração das Doze Horas\nLEITURA BREVE Lm 1,16-17 a\nEis que choro, vertem lágrimas os meus olhos, pois longe de mim está quem me consola, animando meu coração. Maus filhos estão consternados porque o inimigo triunfou. Sião estende sua mão, sem que ninguém a console.\nV. Ouvi, povos todos, e vede a minha dor.\nR. Ouvi meus gemidos; não há ninguém que me console.\n\nOração das Quinze Horas\nLEITURA BREVE Lm l,20a.2,13\nOlha, Senhor, quão angustiado estou: fervem as minhas entranhas, revolve-se dentro de mim o coração. A quem te igualarei para consolar-te, virgem, filha de Sião? Porque grande como o mar é tua ruína: quem poderá curar-te?\nV. Chorando, vão semear a semente.\nR. Quem semeia com lágrimas, cantando há de ceifar.\n\nOração\n\nVésperas\nHino\n\nSim, no Calvário, ó Mãe, tu choraste, ao pé da cruz, traspassada de dor:\ncomo pudeste sofrer tanto assim,\nsem sucumbir, nem fugir, nem gritar?\n\nNada, porém, nos relata a Escritura\nque Filho ou Mãe então tenham chorado; do Filho diz-se que exorta as mulheres:\n\"Por mim não chorem, mas sim por seus filhos!\"\n\nDo alto do monte, no entanto, ele chora sobre a cidade que o amor recusara; chora também pela morte de Lázaro: lamenta a perda do amigo querido!\n\nMas, por que choram as trevas da noite suor de sangue e de lamentações?\nMãe, por acaso, tu lá não estavas? Sem Mãe, se sente perdido até Cristo!\n\nNão diz o Texto que tenhas chorado, recorda apenas o que tu disseste, quando no templo teu Filho perderas: \"Teu pai e eu, tão aflitos...\", e basta!\n\nO Mãe, ó Cristo, ensinai-nos também como é difícil chorar retamente:\nchorar sabermos o pranto dos justos e no alto monte mantermos silêncio.\n\nNão se profanem a dor, nem a morte:\ncoisa mais bela no mundo não há\nque o pranto humano sabermos chorar, sermos assim tua igreja silente.\nSalmodia\nAnt. 1 Junto à cruz de Jesus estava Maria, sua Mãe.\nSalmo 115\nLamentação do justo sofredor que confia no Senhor.\nDeixarei de beber o cálice que o Pai me deu? (Jo 18,11).\n    • Guardei a minha fé, mesmo dizendo:\n* \"É demais o sofrimento em minha vida!\"\n    • Confiei, quando dizia na aflição: *\n\"Todo homem é mentiroso! Todo homem!\"\n    • Que poderei retribuir ao Senhor Deus * por tudo aquilo que ele fez em meu favor?\n    • Elevo o cálice da minha salvação, * invocando o nome santo do Senhor.\n    • Vou cumprir minhas promessas ao Senhor * na presença de seu povo reunido.\n    • É sentida por demais pelo Senhor * a morte de seus santos, seus amigos.\n= Eis que sou o vosso servo, ó Senhor, † vosso servo que nasceu de vossa serva; * mas me quebrastes os grilhões da escravidão!\n    • Por isso oferto um sacrifício de louvor, * invocando o nome santo do Senhor.\n    • Vou cumprir minhas promessas ao Senhor * na presença de seu povo reunido;\n    • nos átrios da casa do Senhor, * em teu meio, ó cidade de Sião!\nAnt. 1 Junto à cruz de Jesus estava Maria, sua Mãe. Oração sálmica\nSenhor, vosso Filho pregado na cruz aceitou o cálice da nossa salvação. Inocente, entregou-se por nós pecadores, e sua morte foi preciosa aos vossos olhos. Por isso, vos pedimos: dai-nos beber cada dia o cálice da paixão, para que, ao findar esta vida, nos apresentemos diante de vós como oferta agradável. Por Cristo nosso Senhor.\n\nAnt. 2 Jesus, do alto da cruz, entrega à Virgem Maria o discípulo amado, e a proclama Mãe de todos os homens.\nSalmo 140,1-9\nA oração do justo sofredor sobe como incenso até junto de Deus\nEntregou-se por nós a Deus, como oferta e sacrifício de suave odor (Ef 5,2).\n-Senhor, eu clamo por vós, socorrei-me; * quando eu grito, escutai minha voz.\n    • Minha oração suba a vós como incenso, * e minhas mãos, como oferta da tarde!\n    • Ponde uma guarda em minha boca, Senhor, * e vigias às portas dos lábios!.\n\n    • Meu coração não deixeis inclinar-se * às obras más nem às tramas do crime;\n    • que eu não seja aliado dos ímpios, * nem partilhe de suas delícias!\n= Se o justo me bate é um favor;† porém jamais os perfumes dos ímpios * sejam usados na minha cabeça!\n    • Continuarei a orar fielmente, * enquanto eles se entregam ao mal!\n= Seus juízes, que tinham ouvido † as suaves palavras que eu disse, * do rochedo já foram lançados.\n= Como a mó rebentada por terra, † os seus ossos estão espalhados *\ne dispersos à boca do abismo.\n    • A vós, Senhor, se dirigem meus olhos, * em vós me abrigo: poupai minha vida.\n    • Senhor, guardai-me do laço que armaram * e da armadilha dos homens malvados.\n\nAnt. 2 Jesus, do alto da cruz, entrega à Virgem Maria o discípulo amado, e a proclama Mãe de todos os homens.\nOração sálmica\nPai santo, ao Cordeiro sem mancha, imolado no altar da cruz, quisestes associar a Virgem sua Mãe; concedei-nos que, unidos a ela, possamos transformar este sacrifício vespertino na oferta de uma vida santa. Por Cristo nosso Senhor.\nAnt.3 Ao discípulo amado e a toda a humanidade Cristo entrega a Virgem Maria para que a recebam como mãe.\nCântico (lPd 2,21-24)\nCristo, servo de Deus, ntregou-se voluntariamente à paixão.\n= O Cristo por nós padeceu, †\ndeixou-nos o exemplo a seguir. * Sigamos, portanto, seus passos!\nPecado nenhum cometeu, *\nnem houve engano em seus lábios.\n= Insultado, ele não insultava; † ao sofrer e ao ser maltratado, * ele não ameaçava vingança; entregava, porém, sua causa * Aquele que é justo juiz.\nCarregou sobre si nossas culpas * em seu corpo, no lenho da cruz,\n= para que, mortos aos nossos pecados, † na justiça de Deus nós vivamos. *\nPor suas chagas nós fomos curados.\nAnt.3 Ao discípulo amado e a toda a humanidade Cristo entrega a Virgem Maria para que a recebam como mãe.\nOração sobre o cântico\nSenhor, ao contemplarmos Cristo suspenso na cruz, suscitai nosso amor por ele. Inocente, carregou o peso dos nossos pecados e, manso, sujeitou-se à condenação injusta. Ajudai-nos, Senhor, a enfrentar as dificuldades da vida e a nunca retribuir mal com mal. Por Cristo nosso Senhor.\nLEITURA BREVE Hb 9,26-28\nIrmãos, foi uma vez por todas, no fim dos tempos, que Cristo se manifestou para abolir o pecado através do seu próprio sacrifício. E como é um fato que os homens devem morrer uma só vez, depois do que vem o julgamento, do mesmo modo, Cristo foi oferecido uma vez por todas para tirar os pecados da multidão. Ele aparecerá uma segunda vez, exclusão feita ao pecado, àqueles que o esperam para a salvação.\nRESPONSÓRIO BREVE\nR. Aproximemo-nos confiantes de Cristo, * para alcançarmos misericórdia e graça e obtermos a ajuda necessária.\nV. Dele a Virgem Maria nos obtém o dom da eterna salvação.\nR. Para alcançarmos misericórdia e graça e obtermos a ajuda necessária.\nV. Glória ao Pai, ao Filho e ao Espírito Santo.\nR. Aproximemo-nos confiantes de Cristo, para alcançarmos misericórdia e graça e obtermos a ajuda necessária.\nCântico evangélico\nAnt. Ao cair da tarde, o Senhor Jesus resgata com seu sangue o povo de Deus; Maria, Mãe da Igreja, sofre a seu lado.\nPreces\nRecordando o sacrifício vespertino que Jesus, na cruz, ofereceu ao Pai pela salvação do mundo, rezemos dizendo:\n\nR. Não permitais que se percam, Senhor, os irmãos que redimistes.\nCristo nosso Salvador, em vossa paixão, uma espada traspassou o coração da Virgem Maria;\n    • não permitais que nossa fé esmoreça na dúvida e nossa esperança se abale.\nJesus, nosso irmão, vós que no Calvário nos entregastes como mãe a vossa própria Mãe;\n    • concedei que possamos amá-la como vós a amastes, para sermos seus filhos verdadeiros. Cristo, nosso Mestre, do alto da cruz, nos revelastes plenamente o vosso mistério;\n    • fazei que, desprezando a sabedoria deste mundo, assi milemos a loucura da cruz. Cristo, nosso Rei, que transformastes o patíbulo da cruz em trono de glória;\n    • convertei nossos corações à vossa mensagem, para que, servindo-nos uns aos outros, possamos ser os primeiros a reinar junto convosco.\nCristo, nosso Sacerdote, que do altar da cruz descestes para libertar os justos das trevas da morte;\n    • fazei que nossos irmãos e irmãs defuntos ouçam a voz que os chama para a glória eterna.\n[A oração que Jesus havia ensinado ressoa em suas palavras na cruz: para que possamos ter seus mesmos sentimentos, contemplando-o na cruz, rezemos como ele nos ensinou: Pai nosso...].\n\nOração\n    15 de setembro"}]}};
